  Content_110201_04e = {
    ContentEN = "Filthoids close in from all sides. Defeat them.",
    ContentFR = "Des Souillés errants affluent de toutes parts. Éliminez-les.",
    ContentJP = "さまよう穢獣が四方から押し寄せてきた。倒そう。",
