  Content_400122_1 = {
    ContentEN = "The place where I first met Psyche. In this cold city, she was the first person to show me real kindness.",
    ContentFR = "L’endroit où j’ai rencontré Psyche pour la première fois. Dans cette ville glaciale, elle fut la première à me considérer comme {性别:un véritable ami|une véritable amie}.",
    ContentJP = "{性别:僕|私}がサイキと初めて出会った場所。この冷たい街で、彼女は初めて心から{性别:僕|私}を友として接してくれた人だった。",
    ContentKR = "나와 프시케가 처음 만난 장소. 이 차가운 도시에서, 나를 진정한 친구로 대해 준 사람은 프시케가 처음이었다.",
    ContentTC = "我和賽琪第一次見面的地方。在這座冰冷的城市裡，她是第一個將我當做朋友真心對待的人。",
    TextMapContent = "我和赛琪第一次见面的地方。在这座冰冷的城市里，她是第一个将我当做朋友真心对待的人。",
    TextMapId = "Content_400122_1"
  },
  Content_400122_2 = {
