  DUNGEON_RESCUE_101 = {
    ContentEN = "Locate the <H>Secret Cell</> that's holding the target, crack the mechanism, and secure the target.",
    ContentFR = "Repérez la <H>Cellule secrète</> où le prisonnier est détenu, déverrouillez le mécanisme et retrouvez la cible.",
    ContentJP = "<Highlight>密室エリア</>に閉じ込められた目標を探し出し、トラップを解いて救出しましょう。",
    ContentKR = "목표가 갇힌 <Highlight>밀실 구역</>을 찾아 밀실 장치를 해제하고 목표를 찾으세요.",
    ContentTC = "找到目標被困的<Highlight>密室區域</>，解開密室機關，從中找到目標。",
    TextMapContent = "找到目标被困的<Highlight>密室区域</>，解开密室机关，从中找到目标。",
    TextMapId = "DUNGEON_RESCUE_101"
  },
  DUNGEON_RESCUE_102 = {
    ContentEN = "Try to avoid detection by the enemy <H>Patrollers</> around the <H>Secret Cells</>. If spotted, defeat them quickly to prevent them from sounding the alarm.",
    ContentFR = "Lors de vos déplacements dans la <H>zone des Cellules secrètes</>, évitez d’être repéré par les <H>patrouilles ennemies</>.\n Si vous êtes découvert, éliminez rapidement vos assaillants pour les empêcher de donner l’alerte.",
    ContentJP = "<Highlight>密室エリア</>での行動中は、敵の<Highlight>巡回部隊</>に発見されないほう注意してください。発見された場合は、敵を倒して警報発信を阻止しましょう。",
    ContentKR = "<Highlight>밀실 구역</>에서 적의 <Highlight>순찰 유닛</>에게 발각되지 않도록 주의하세요. 발각되면 적을 처치하여 경보를 막을 수 있습니다.",
    ContentTC = "在<Highlight>密室區域</>行動時，盡量不要被敵方的<Highlight>巡邏單位</>發現。如果不慎被發現，可以通過擊敗對方阻止其報警。",
    TextMapContent = "在<Highlight>密室区域</>行动时，尽量不要被敌方的<Highlight>巡逻单位</>发现。如果不慎被发现，可以通过击败对方阻止其报警。",
    TextMapId = "DUNGEON_RESCUE_102"
  },
  DUNGEON_RESCUE_103 = {
    ContentEN = "If you fail to stop the Patrollers from sounding the alarm, the target will be in danger. Find the target before the <H>countdown</> expires, or the Commission will fail.",
    ContentFR = "Si les patrouilles parviennent à donner l’alerte, la cible sera en danger. Trouvez-la avant la fin du <H>décompte</>, sans quoi la mission échouera.",
    ContentJP = "警報を阻止できなかった場合、目標の身が危険に晒されます。目標が被害を受けるまでの<Highlight>カウントダウン</>が終わる前に目標を発見できなければ依頼失敗となります。",
    ContentKR = "순찰 유닛의 경보를 막지 못하면 목표가 위험에 빠집니다. 목표의 피해 <Highlight>카운트다운</> 종료 전에 목표를 찾아야 합니다. 시간이 종료되면 의뢰에 실패합니다.",
    ContentTC = "如果沒能阻止巡邏單位報警，目標便會陷入危險。必須在目標被害<Highlight>倒計時</>結束前找到目標，否則委託失敗。",
    TextMapContent = "如果没能阻止巡逻单位报警，目标便会陷入危险。必须在目标被害<Highlight>倒计时</>结束前找到目标，否则委托失败。",
    TextMapId = "DUNGEON_RESCUE_103"
  },
  DUNGEON_RESCUE_104 = {
    ContentEN = "After rescuing the target, escort them to the Evacuation Point. Please vigilantly ensure their safety throughout the trip.",
    ContentFR = "Une fois la cible libérée, escortez-la jusqu’au Point d’évacuation tout en veillant constamment à sa sécurité.",
    ContentJP = "目標救出後は撤退ポイントまで護衛します。移動中は目標の安全に気を配り、ダメージを受けて倒れないよう警戒してください。",
    ContentKR = "목표를 구출한 후 철수 포인트로 호위하세요. 이동 중 목표의 안전에 주의를 기울여 목표가 부상을 입어 쓰러지지 않도록 하세요.",
    ContentTC = "救出目標後將其護送至撤離點，途中請時刻關註目標的安危，避免目標受傷倒下。",
    TextMapContent = "救出目标后将其护送至撤离点，途中请时刻关注目标的安危，避免目标受伤倒下。",
    TextMapId = "DUNGEON_RESCUE_104"
  },
  DUNGEON_RESCUE_105 = {
    ContentEN = "The Commission is considered complete once the target is successfully escorted to the Evacuation Point.",
    ContentFR = "La mission sera accomplie une fois la cible arrivée saine et sauve au Point d’évacuation.",
    ContentJP = "目標を無事に撤退ポイントまで護衛すれば、依頼完了となります。",
    ContentKR = "목표를 안전하게 철수 포인트로 호위하면 의뢰가 완료됩니다.",
    ContentTC = "安全護送目標抵達撤離點，即可完成委託。",
    TextMapContent = "安全护送目标抵达撤离点，即可完成委托。",
    TextMapId = "DUNGEON_RESCUE_105"
  },
