  Event_Des_103030 = {
    ContentEN = "Capture our journey in light and shadow. Preserve the moments we've shared.",
    ContentFR = "Immortaliser le passé dans les jeux d’ombre et de lumière, et garder une trace de notre voyage.",
    ContentJP = "過ぎし日を光と影に刻み、私たちの旅を記録する。",
    ContentKR = "빛과 그림자로 지난날을 아로새기고, 우리의 여정을 기록하세요.",
