  Guide_GuildBoss_1 = {
    ContentEN = "A new Elite Threat Protocol mode has been added to the Guild. Team up with guild members to defeat powerful enemies and earn rewards.",
    ContentFR = "La guilde accueille désormais le mode « Assaut d’élite ». Coopérez avec les membres de la guilde pour terrasser de puissants ennemis et obtenir des récompenses.",
    ContentJP = "「協会」に「強敵対策」が追加されました。協会メンバーと協力して強敵を討伐し、報酬を獲得しましょう。",
    ContentKR = "길드에 강적 대책 콘텐츠가 추가되었습니다. 길드원들과 함께 강력한 적을 토벌하고 보상을 획득하세요.",
    ContentTC = "協會新增強敵對策玩法，與協會成員共同討伐強大的敵人，獲取獎勵。",
    TextMapContent = "协会新增强敌对策玩法，与协会成员共同讨伐强大的敌人，获取奖励。",
    TextMapId = "Guide_GuildBoss_1"
  },
  Guide_GuildBoss_2 = {
    ContentEN = "This mode features a rotating set of Extreme-threat enemies that change every 6 weeks, with one enemy available each week.",
    ContentFR = "Dans ce mode, un groupe d’ennemis d’élite est remplacé toutes les 6 semaines, et l’ennemi affronté change chaque semaine.",
    ContentJP = "強敵は6週間ごとに入れ替わり、毎週1体ずつ挑戦できます。",
    ContentKR = "이 콘텐츠의 강적 조합은 6주마다 교체되며, 매주 한 명의 강적을 전환해 전투를 진행합니다.",
    ContentTC = "該玩法設定為每六週更換一組強敵，每週切換一個強敵進行戰鬥。",
    TextMapContent = "该玩法设定为每六周更换一组强敌，每周切换一个强敌进行战斗。",
    TextMapId = "Guide_GuildBoss_2"
  },
  Guide_GuildBoss_3 = {
    ContentEN = "Guild members deal damage to Extreme-threat enemies together to increase trial progress and earn guild rewards. Additional individual rewards are granted based on each member's personal performance.",
    ContentFR = "Les membres de la guilde infligent ensemble des dégâts aux ennemis d’élite afin d’augmenter la progression de l’assaut et d’obtenir des récompenses de guilde.\nDes récompenses individuelles d’assaut sont également attribuées selon les performances personnelles de chaque membre.",
    ContentJP = "協会全員で強敵にダメージを与えると、演習進捗が上昇し、協会報酬を獲得できます。\nさらに、各メンバーの個人成績に応じて追加個人報酬が付与されます。",
    ContentKR = "길드원이 함께 강적에게 대미지를 입히면 훈련 진행도가 증가하고 길드 보상을 획득합니다.\n 또한 길드원 개인의 훈련 진행도에 따라 추가로 개인 대책 보상이 지급됩니다.",
    ContentTC = "協會成員共同對強敵造成傷害，可增加演練進度，獲得協會獎勵；\n並將根據成員個人演練發揮，額外發放單人對策獎勵。",
    TextMapContent = "协会成员共同对强敌造成伤害，可增加演练进度，获得协会奖励；\n并将根据成员个人演练发挥，额外发放单人对策奖励。",
    TextMapId = "Guide_GuildBoss_3"
  },
  Guide_GuildBoss_4 = {
    ContentEN = "After guild members complete Protocols together, the number of Protocols completed determines which items are unlocked for purchase in the Guild Shop.",
    ContentFR = "Une fois les assauts accomplis par les membres de la guilde, certains objets de la boutique de guilde seront débloqués à l’achat en fonction du nombre d’assauts terminés.",
    ContentJP = "協会が共同で対策を完了すると、対策の完了数に応じて、協会ショップの一部のアイテムの購入権限が解放されます。",
    ContentKR = "길드원이 함께 대책을 완료하면, 완료한 대책 수에 따라 길드 상점 내 일부 상품의 구매 권한이 해제됩니다.",
    ContentTC = "協會成員共同完成對策後，可根據完成對策數量，解鎖協會商店部分商品的購買權限。",
    TextMapContent = "协会成员共同完成对策后，可根据完成对策数量，解锁协会商店部分商品的购买权限。",
    TextMapId = "Guide_GuildBoss_4"
