  HomePianoDes_1008002 = {
    ContentEN = "Do the sleepy Lunotress dream of Luno Coins?",
    ContentFR = "La servante somnolente rêve-t-elle de Pièces Luno ?",
    ContentJP = "眠たがりのルーナ族のバーテンダーは、ルーナコインの夢を見るか？",
