    TextMapId = "HomePianoDes_1011007"
  },
  HomePianoDes_1012001 = {
    ContentEN = "May this song restore balance to heaven and earth.",
    ContentFR = "Que ce chant rétablisse l’équilibre entre ciel et terre.",
    ContentJP = "この歌とともに、天地の均衡を鋳え直せ",
    ContentKR = "이 노래를 벗 삼아, 천하를 다시 바로잡으리.",
    ContentTC = "伴此歌，讓天地重鑄天平",
    TextMapContent = "伴此歌，让天地重铸天平",
    TextMapId = "HomePianoDes_1012001"
  },
  HomePianoDes_1013001 = {
    ContentEN = "Dust rises along the capital road, veiling gilded reins and ornate carriages.",
    ContentFR = "La poussière s’élève sur la route de la capitale, voilant rênes dorées et carrosses ouvragés.",
    ContentJP = "砂ぼこりが舞い上がり、輦車が行き交う。",
    ContentKR = "화려한 안장과 수레바퀴가 오가고, 거리에는 먼지가 피어오른다.",
    ContentTC = "紫陌飛塵，雕鞍繡轂。",
    TextMapContent = "紫陌飞尘，雕鞍绣毂。",
    TextMapId = "HomePianoDes_1013001"
  },
  HomePianoDes_1013002 = {
    ContentEN = "A city of a thousand years, still alive with the restless bustle of the world.",
    ContentFR = "Haojing, cité millénaire, toujours animée par le tumulte du monde.",
    ContentJP = "千年の皓京、賑わいに満ちた町。",
    ContentKR = "천 년의 도읍 호경에 사람 사는 냄새가 피어오른다.",
    ContentTC = "千年皓京，煙火人間。",
    TextMapContent = "千年皓京，烟火人间。",
    TextMapId = "HomePianoDes_1013002"
  },
  HomePianoDes_1013003 = {
    ContentEN = "The fragrance lingers; the xiao weeps low.",
    ContentFR = "Le parfum de Jiaolan demeure, tandis que le xiao laisse entendre une plainte sourde.",
    ContentJP = "あの香りは昔のまま、笛の音はむせび泣く。",
    ContentKR = "산초향은 예전과 같건만, 퉁소 소리만 구슬피 흐느끼네.",
    ContentTC = "椒香如故，簫聲嗚咽。",
    TextMapContent = "椒香如故，箫声呜咽。",
    TextMapId = "HomePianoDes_1013003"
  },
  HomePianoDes_1013004 = {
    ContentEN = "The fragrance lingers; the qin speaks of years gone by.",
    ContentFR = "Le parfum de Jiaolan demeure, tandis que le piano murmure les années écoulées.",
    ContentJP = "あの香りは昔のまま、琴は流れる歳月を語る。",
    ContentKR = "산초향은 예전과 같건만, 현 소리만이 지난 세월을 읊조리네.",
    ContentTC = "椒香如故，琴訴流年。",
    TextMapContent = "椒香如故，琴诉流年。",
    TextMapId = "HomePianoDes_1013004"
  },
  HomePianoDes_1013005 = {
    ContentEN = "Beyond every peak lies a higher sky.",
    ContentFR = "Au-delà des cimes entassées, un autre ciel se révèle.",
    ContentJP = "幾重にも連なる峰々、その山の外にもまた山がある。",
