    ContentTC = "緣起何因，剎那而生。",
    TextMapContent = "缘起何因，刹那而生。",
    TextMapId = "HomePianoDes_1013007"
  },
  HomePianoDes_1013008 = {
    ContentEN = "In every ingenious working, wonder quietly unfolds.",
    ContentFR = "Dans l’ingéniosité de Jishu, les merveilles se dévoilent en silence.",
    ContentJP = "機枢の妙なるからくり、その内にはまた別天地がある。",
