  MonsterRushEvent_Wuyou_DungeonName07 = {
    ContentEN = "A Tomorrow Unburdened",
    ContentFR = "Un lendemain sans souci",
    ContentJP = "ゆらめく明日",
    ContentKR = "여유로운 내일",
    ContentTC = "悠然飄搖的明日",
    TextMapContent = "悠然飘摇的明日",
