  },
  PROLOGUE_SELECTGUN_DESC_20498 = {
    ContentEN = "Has a <Highlight>slower fire rate</>, capable of <Highlight>firing multiple bullets at the same time</> to inflict substantial damage on <Highlight>nearby</> enemies.",
