  Pack_Name_Battle_Dispatch_Des = {
    ContentEN = [[
The pack may contain:
Luno Memento
Damaged Sal Volatile
Stone Powder
Vermilion Teardrop
Creeping Tendrils
Filthoid Clot
Chain]],
    ContentFR = "Ouvrir ce coffret permet d’obtenir aléatoirement les objets suivants :\n- Souvenir des Lunariens\n- Sel volatil endommagé\n- Poudre de pierre\n- Larme vermillon\n- Vrille rampante\n- Grumeau de Souillé\n- Chaîne",
    ContentJP = "パックを開けると以下のアイテムを入手できます：\n ルーナ族の印\n 壊れた気つけ薬\n 砕石の粉\n 深紅の雫\n 地伏せ枝\n 穢獣の凝脂\n チェーン",
    ContentKR = "보상 패키지 오픈 시 등장 가능 아이템:\n루나의 증표\n파손된 스멜링 솔트\n석재 분말\n붉은 눈물방울\n땅의 가지\n필토이드의 응고체\n사슬",
    ContentTC = "開啟獎勵包後可能獲取以下道具：\n皎皎之民的信物\n破損的嗅鹽\n石料粉末\n朱紅淚滴\n匍地枝\n穢獸凝脂\n鎖鏈",
    TextMapContent = "开启奖励包后可能获取以下道具：\n皎皎之民的信物\n破损的嗅盐\n石料粉末\n朱红泪滴\n匍地枝\n秽兽凝脂\n锁链",
    TextMapId = "Pack_Name_Battle_Dispatch_Des"
  },
