  },
  PartyReward_Name_540102 = {
    ContentEN = "Bloodstained Scalpel",
    ContentFR = "Scalpel ensanglanté",
    ContentJP = "血のついたメス",
    ContentKR = "피 묻은 메스",
    ContentTC = "染血的手術刀",
    TextMapContent = "染血的手术刀",
    TextMapId = "PartyReward_Name_540102"
  },
  PartyReward_Name_540103 = {
    ContentEN = "Compact Recording Device",
    ContentFR = "Enregistreur compact",
    ContentJP = "小型録音機",
    ContentKR = "소형 녹음기",
    ContentTC = "小型錄音設備",
    TextMapContent = "小型录音设备",
    TextMapId = "PartyReward_Name_540103"
  },
  PartyTopic_Description_110101 = {
    ContentEN = "She poured strange ingredients into the pot, mixing in the purest love and care.",
    ContentFR = "Elle versa d’étranges ingrédients au fond du chaudron, y mêlant la maladroite tendresse qu’elle portait au fond du cœur.",
    ContentJP = "不思議な食材を鍋に入れてかき混ぜよう。心の底の、不器用で優しい心をほぐすように。",
    ContentKR = "냄비 바닥에 기이한 재료를 넣고 마음속을 배회하는 바보 같은 선의를 휘젓는다.",
    ContentTC = "將奇異的食材倒進鍋底，攪拌著徘徊在心底的、笨拙的善意。",
    TextMapContent = "将奇异的食材倒进锅底，搅拌着徘徊在心底的、笨拙的善意。",
    TextMapId = "PartyTopic_Description_110101"
  },
  PartyTopic_Description_110102 = {
    ContentEN = "You are the reason I must be strong.",
    ContentFR = "Tu es la raison pour laquelle je ne peux fuir.",
    ContentJP = "あなたが、私が逃げられない理由。",
    ContentKR = "당신이 바로 내가 피하지 못하는 이유.",
    ContentTC = "你是我無法躲避的理由。",
    TextMapContent = "你是我无法躲避的理由。",
    TextMapId = "PartyTopic_Description_110102"
  },
  PartyTopic_Description_110103 = {
    ContentEN = "This shore is my whole world, a cage forged just for me.",
    ContentFR = "Cette rive est tout mon monde — et le monde entier est ma cage.",
    ContentJP = "此岸が、私の世界のすべて。そして、私を閉じこめるために世界が築いた牢獄。",
    ContentKR = "이 기슭이 바로 내 세상이자, 세상이 날 위해 만든 감옥이야.",
    ContentTC = "此岸是我的整個世界，也是整個世界為我鑄造的牢籠。",
    TextMapContent = "此岸是我的整个世界，也是整个世界为我铸造的牢笼。",
    TextMapId = "PartyTopic_Description_110103"
  },
  PartyTopic_Description_110104 = {
    ContentEN = "All has ended, and all begins anew.",
    ContentFR = "Tout est fini, et tout recommence.",
    ContentJP = "すべてが終わり、すべてが始まる。",
    ContentKR = "모든 것이 끝나고, 모든 것이 시작되었다.",
    ContentTC = "一切結束了，一切開始了。",
    TextMapContent = "一切结束了，一切开始了。",
    TextMapId = "PartyTopic_Description_110104"
  },
  PartyTopic_Description_110201 = {
    ContentEN = "In a quiet house, two exiles from distant lands keep each other company.",
    ContentFR = "Dans une demeure silencieuse, deux exilées venues d’ailleurs trouvent refuge l’une auprès de l’autre.",
    ContentJP = "静まり返った屋敷で、流離う異郷の客人二人は身を寄せ合っていた。",
    ContentKR = "고요한 저택 안, 머나먼 타향을 떠도는 두 이방인이 서로 어깨를 기댄다.",
    ContentTC = "靜寂的宅邸，兩位流離的他鄉之客相偎相依。",
    TextMapContent = "静寂的宅邸，两位流离的他乡之客相偎相依。",
    TextMapId = "PartyTopic_Description_110201"
  },
  PartyTopic_Description_110202 = {
    ContentEN = "She had pulled this little stunt countless times before to test how much her daughter had improved. Only this time... it would be the last.",
    ContentFR = "Elle lui avait joué ce petit tour d’innombrables fois, afin d’éprouver les progrès de sa fille. Seulement, cette fois... ce serait la dernière.",
    ContentJP = "彼女はこれまで何度もこんないたずらをして、娘の腕を試してきた。ただし、これが最後の一度となった。",
    ContentKR = "어머니는 딸의 실력을 시험하기 위해 수없이 이런 장난을 쳐 왔다. 하지만, 장난은 이번이 끝이다.",
    ContentTC = "她曾無數次這樣惡作劇，藉此試驗女兒的身手。只是，這是最後一次了。",
    TextMapContent = "她曾无数次这样恶作剧，藉此试验女儿的身手。只是，这是最后一次了。",
    TextMapId = "PartyTopic_Description_110202"
  },
  PartyTopic_Description_110203 = {
    ContentEN = "Tears still cling to a mother's face, bearing the one message the girl most dreads to hear.",
    ContentFR = "Des traces de larmes marquent encore le visage familier de cette mère, venue apporter à la jeune fille la nouvelle qu’elle redoutait plus que tout.",
    ContentJP = "見慣れた母の顔には涙の跡があり、少女が最も聞きたくなかった知らせを運んできた。",
    ContentKR = "어머니의 익숙한 얼굴 위에는 눈물 자국이 있었고, 소녀가 가장 바라지 않는 소식을 전해왔다.",
    ContentTC = "那位母親熟悉的臉上掛著淚痕，捎來女孩最不願聽到的訊息。",
    TextMapContent = "那位母亲熟悉的脸上挂着泪痕，捎来女孩最不愿听到的讯息。",
    TextMapId = "PartyTopic_Description_110203"
  },
  PartyTopic_Description_110204 = {
    ContentEN = "She has made her choice.",
    ContentFR = "À présent, elle a fait son choix.",
    ContentJP = "今、彼女はもう選び終えている。",
    ContentKR = "이제 그녀는 선택을 마쳤다.",
    ContentTC = "現在，她已經做好了選擇。",
    TextMapContent = "现在，她已经做好了选择。",
    TextMapId = "PartyTopic_Description_110204"
  },
  PartyTopic_Description_110301 = {
    ContentEN = "A playwright once told me that to drive a protagonist into action, you must first strip away all their hope. How I wish reality didn't work that way.",
    ContentFR = "Un dramaturge m’a un jour confié qu’avant de pousser un héros à agir,\nil faut d’abord lui arracher tout espoir.\nPuissé-je seulement croire que la réalité ne fonctionne pas ainsi.",
    ContentJP = "ある劇作家がこう言った。「物語の主人公が動き出すためには、まずそのすべての希望を奪え」と。その言葉を聞いたとき、僕はただ願った。現実が、そうならないことを。",
    ContentKR = "어느 극작가는 내게 이렇게 말했다. 이야기 속의 주인공이 행동하게 하려면, 먼저 그로부터 모든 희망을 앗아 가야 한다고. 나는 현실만큼은 그렇지 않길 바랐다.",
    ContentTC = "一位劇作家曾告訴我，為了促使故事的主人公做出行動，必須先奪走他的一切希望。我多希望現實不是這樣。",
    TextMapContent = "一位剧作家曾告诉我，为了促使故事的主人公做出行动，必须先夺走他的一切希望。我多希望现实不是这样。",
    TextMapId = "PartyTopic_Description_110301"
  },
  PartyTopic_Description_110302 = {
    ContentEN = "When hope is shattered and every path of retreat is severed, the protagonist can never return to the life they once knew. I once tried to delay that moment for as long as I could.",
    ContentFR = "Lorsque l’espoir s’effondre et que toute échappatoire disparaît, le protagoniste ne peut plus jamais revenir à la vie qu’il connaissait.\nJ’ai tenté, autant que possible, de retarder ce moment.",
    ContentJP = "希望が打ち砕かれ、退く道を断たれた時、主人公はもう元の生活には戻れない。この瞬間を少しでも遅らせようと僕は試みた。",
    ContentKR = "희망이 산산조각 나고, 퇴로가 막히면, 주인공은 더 이상 원래의 삶으로 돌아갈 수 없게 된다. 나는 그 순간을 어떻게든 늦추려 했었다.",
    ContentTC = "當希望被粉碎、退路被阻斷，主人公便再也回不到原來的生活。我曾試圖讓這一刻來得更晚一些。",
    TextMapContent = "当希望被粉碎、退路被阻断，主人公便再也回不到原来的生活。我曾试图让这一刻来得更晚一些。",
    TextMapId = "PartyTopic_Description_110302"
  },
  PartyTopic_Description_110303 = {
    ContentEN = "Audiences love twists and surprises, so the stories playwrights weave must ebb and flow. But my story... it seems to have but one direction — downward, ever deeper, an endlessly spiralling descent.",
    ContentFR = "Les spectateurs raffolent des rebondissements ; les dramaturges n’ont donc de cesse de faire ondoyer leurs récits. Mais mon histoire, elle, ne connaît qu’une seule direction : vers le bas — encore, toujours, inexorable, dans une chute sans fin.",
    ContentJP = "観客はどんでん返しやサプライズを好む。故に作家が生み出す物語は必ず起伏に富むものだ。だが、僕の物語は、ひたすら下へ、下へ、下へと……果てしなく落ち続けていた。",
    ContentKR = "관객들은 반전과 놀라움을 좋아한다. 그래서 극작가의 이야기엔 늘 기복이 있다. 하지만, 내 이야기는 언제나 아래로, 아래로, 그리고 아래로... 한없이 추락할 뿐이다.",
    ContentTC = "觀眾喜歡轉折和驚喜，所以劇作家筆下的故事情節總是起起伏伏。但，我的故事，似乎從來只有向下、向下、向下……無盡地墜落。",
    TextMapContent = "观众喜欢转折和惊喜，所以剧作家笔下的故事情节总是起起伏伏。但，我的故事，似乎从来只有向下、向下、向下……无尽地坠落。",
    TextMapId = "PartyTopic_Description_110303"
  },
  PartyTopic_Description_110304 = {
    ContentEN = "Perhaps I was never destined for a beautiful story — but even so, I have the right to choose how it ends.",
    ContentFR = "Peut-être n’étais-je pas destiné à une belle histoire. Mais j’ai tout de même le droit d’en choisir la fin.",
    ContentJP = "ハッピーエンドとは無縁の物語の主役として、結末を選ぶ権利くらいはあるはずだ。",
    ContentKR = "어쩌면 나는 아름다운 이야기와는 거리가 먼 운명일지도 모른다. 하지만, 이런 나에게도 마지막 결말을 선택할 권리가 있다.",
    ContentTC = "或許我註定無法擁有一個美好的故事，但我仍有權利為自己選擇最後的結局。",
    TextMapContent = "或许我注定无法拥有一个美好的故事，但我仍有权利为自己选择最后的结局。",
    TextMapId = "PartyTopic_Description_110304"
  },
  PartyTopic_Description_150201 = {
    ContentEN = "Sometimes, false hope is more cruel than despair itself, as it prolongs yesterday's suffering into a future where closure should have already been found.",
    ContentFR = "Parfois, un espoir déformé se révèle plus cruel que le désespoir lui-même : il prolonge les souffrances d’hier dans un futur où elles auraient déjà dû s’éteindre.",
    ContentJP = "歪んだ希望は、時に絶望よりも残酷だ。昨日の苦しみを、進むべき未来へと引きずり込んでしまうから。",
    ContentKR = "왜곡된 희망은 때로 절망보다 더 잔혹하여, 고통스러운 어제를 본래 나아가야 할 미래까지 이어지게 한다.",
    ContentTC = "扭曲的希望有時比絕望更加殘酷，它將苦難的昨日延續至本應向前的未來。",
    TextMapContent = "扭曲的希望有时比绝望更加残酷，它将苦难的昨日延续至本应向前的未来。",
    TextMapId = "PartyTopic_Description_150201"
  },
  PartyTopic_Description_150202 = {
    ContentEN = "Though the winds of tomorrow will one day erase every trace we leave behind, the moments of glory we once shared will forever glow in the memories of those who remain.",
    ContentFR = "Même si le vent de demain emportera toute trace de notre passage, les instants où nous avons brillé resteront à jamais gravés dans la mémoire de ceux qui demeurent.",
    ContentJP = "たとえ明日の風がすべての痕跡を消し去ったとしても、私たちの輝かしい瞬間は、永遠に記憶に刻まれる。",
    ContentKR = "비록 내일의 바람이 우리가 남긴 모든 흔적을 가져가더라도, 한때 빛났던 순간은 기억 속에 영원히 남는다.",
    ContentTC = "即便明日的風終將帶走我們留下的所有痕跡，曾經閃耀的瞬間仍會在記憶中永遠留存。",
    TextMapContent = "即便明日的风终将带走我们留下的所有痕迹，曾经闪耀的瞬间仍会在记忆中永远留存。",
    TextMapId = "PartyTopic_Description_150202"
  },
  PartyTopic_Description_150203 = {
    ContentEN = "We choose to walk the path that leads to the cliff's edge, for along the way, we will be greeted by beautiful wildflowers.",
    ContentFR = "Nous avons choisi d’emprunter cette route qui mène au bord du précipice... parce qu’elle était bordée de fleurs.",
    ContentJP = "私たちは崖へと続く道を選んだ。その道中に咲き誇る美しい花々を見るために――",
    ContentKR = "우리가 절벽으로 향하는 길을 선택하는 건, 그 길에 만발한 꽃들이 함께하기 때문이다.",
    ContentTC = "我們選擇踏上那條通往懸崖的道路，只因一路上會有繁花相伴。",
    TextMapContent = "我们选择踏上那条通往悬崖的道路，只因一路上会有繁花相伴。",
    TextMapId = "PartyTopic_Description_150203"
  },
  PartyTopic_Description_150204 = {
    ContentEN = "Countless tales intertwine, weaving the endless journey that is her life.",
    ContentFR = "Une histoire après l’autre — ainsi se tisse le long récit de sa vie.",
    ContentJP = "一つ一つの物語が繋がり、彼女の果てしない人生を紡いでいる。",
    ContentKR = "하나하나의 이야기가 모여 그녀의 길고도 끝나지 않은 삶이 된다.",
    ContentTC = "一個個故事連起來，便是她漫長未盡的一生。",
    TextMapContent = "一个个故事连起来，便是她漫长未尽的一生。",
    TextMapId = "PartyTopic_Description_150204"
  },
  PartyTopic_Description_150301 = {
    ContentEN = "In the heart of the deepwood, every soul seeks to leave a tale behind — most are woven with vengeance and love.\nYet, the truly awakened leave no shadow in their passing.",
    ContentFR = "Là où les forêts sont épaisses et les roseaux entremêlés, circulent toujours des récits de vagabonds retirés du monde. La plupart parlent de haines et de serments. Mais ceux qui se sont réellement détachés ne laissent derrière eux aucune trace.",
    ContentJP = "木々が生い茂る森や、葦が絡み合う水辺には、いつもどこかに世を忍ぶ侠客の噂が残されている。語られるのは、大抵が恩讐と情の入り混じった物語だ。けれど、真にこの世を捨てた者は、痕ひとつ残さず、ただ風のように消えてゆく。",
    ContentKR = "나무나 갈대가 우거진 숲에는 늘 세상을 등진 협객에 대한 소문이 존재하기 마련이다. 그 이야기들은 대부분 복수나 사랑으로 점철되어 있지만, 진정한 고수는 흔적 하나 남기지 않는다.",
    ContentTC = "但凡樹林茂密或是蘆葦交橫處，總有隱逸的遊俠留下的傳聞。這些故事恩怨情仇居多。然而真正的出世之人，連一點蹤跡也不會留下。",
    TextMapContent = "但凡树林茂密或是芦苇交横处，总有隐逸的游侠留下的传闻。这些故事恩怨情仇居多。然而真正的出世之人，连一点踪迹也不会留下。",
    TextMapId = "PartyTopic_Description_150301"
  },
  PartyTopic_Description_150302 = {
    ContentEN = "Behind every peak lies a hope — and behind every hope, a fading light. Yet looking back, the finest view remains the one he left behind.",
    ContentFR = "Derrière chaque montagne naît un espoir, avant de s’éteindre à son tour. Pourtant, en se retournant, le plus beau paysage reste toujours celui du départ.",
    ContentJP = "山を越えるたびに小さな希望は灯るが、また一つずつ消えていく。\n 振り返れば、旅立つ前の景色こそいちばん美しかった。",
    ContentKR = "산 뒤편에선 늘 희망의 불꽃이 타오르다가도, 하나씩 사그라든다. 돌이켜 보면, 출발하기 전의 경치가 가장 아름다웠다.",
    ContentTC = "每一座山後都有一些希望，但是又一一熄滅。回望之下，出發之前的景致最好。",
    TextMapContent = "每一座山后都有一些希望，但是又一一熄灭。回望之下，出发之前的景致最好。",
    TextMapId = "PartyTopic_Description_150302"
  },
  PartyTopic_Description_150303 = {
    ContentEN = "Scents stir the soul's deep-seated memories; perhaps this is why every heart treasures a different fare, for no two journeys share the same road.",
    ContentFR = "Les odeurs réveillent la mémoire. Peut-être est-ce pour cela que chacun a ses mets de prédilection : nos chemins d’origine ne se ressemblent jamais.",
    ContentJP = "匂いは記憶の扉を開く。好きな食べ物は人それぞれなのは。来し方が違うのだから。",
    ContentKR = "향기는 기억을 불러일으킨다. 사람마다 좋아하는 음식이 다른 것은, 어쩌면 걸어온 길이 다르기 때문일지도 모른다.",
    ContentTC = "氣味會喚醒記憶，也許這就是為什麼每個人偏愛的食物都不一樣，因為彼此的來路也各不相同。",
    TextMapContent = "气味会唤醒记忆，也许这就是为什么每个人偏爱的食物都不一样，因为彼此的来路也各不相同。",
    TextMapId = "PartyTopic_Description_150303"
  },
  PartyTopic_Description_150304 = {
    ContentEN = "Youth in pursuit of the sword ever climbs toward the peak. On and on, until companions grow few. At the summit, none remain, only endless snow upon bowed heads.",
    ContentFR = "Dans la jeunesse, on apprend l’épée en visant toujours plus haut. On marche, on marche encore — les compagnons se font rares. Parvenu au sommet, il ne reste plus personne. Seule la neige demeure, s’accumulant sur la tête.",
    ContentJP = "若き日に剣を学ぶ者は、常に高みを目指す。歩き続けるうちに仲間は減り、頂に立てば、そこにあるのは吹き荒ぶ雪のみ。",
    ContentKR = "어린 시절, 검을 배울 때는 늘 높은 곳을 향했지만, 가다 보면, 길 위의 동료는 점점 줄어들었다. 가장 높은 곳에 올랐을 땐 성성한 백발뿐, 주위엔 아무도 없었다.",
    ContentTC = "少時學劍，總是會向著高處走。走啊，走啊，同路人越來越少，到了最高處，再沒有同伴，只有大雪堆滿頭。",
    TextMapContent = "少时学剑，总是会向着高处走。走啊，走啊，同路人越来越少，到了最高处，再没有同伴，只有大雪堆满头。",
    TextMapId = "PartyTopic_Description_150304"
  },
  PartyTopic_Description_150401 = {
    ContentEN = "Drifting leaves settle on the earth. The wandering returns home at last.",
    ContentFR = "Les feuilles portées par le vent finissent par retomber sur la terre. Ceux qui ont longtemps erré trouvent, eux aussi, le chemin du retour.",
    ContentJP = "舞い落ちた木の葉が地に還るように、彷徨い人もまた、ふるさとへ帰る。",
    ContentKR = "떠돌던 잎새가 땅에 내려앉고, 방황하던 이도 집으로 돌아간다.",
    ContentTC = "飄零的葉子落了地，飄零的人也回家去。",
    TextMapContent = "飘零的叶子落了地，飘零的人也回家去。",
    TextMapId = "PartyTopic_Description_150401"
  },
  PartyTopic_Description_150402 = {
    ContentEN = "The road away from home winds on — long, crooked, and far. You daren't look back.",
    ContentFR = "La route qui s’éloigne de la maison est longue et tortueuse. Et tu n’oses pas te retourner pour regarder derrière toi.",
    ContentJP = "帰り道は、思ったよりも遠く、そして複雑だった。振り返るのが怖くて、ただ前だけを見て歩いていた。",
    ContentKR = "집을 떠나오는 길은 차마 뒤돌아볼 용기가 나지 않을 만큼, 멀고도 험했다.",
    ContentTC = "離家的路，曲折又遙遠，你不敢回頭看。",
    TextMapContent = "离家的路，曲折又遥远，你不敢回头看。",
    TextMapId = "PartyTopic_Description_150402"
  },
  PartyTopic_Description_150403 = {
    ContentEN = "Blood binds. Cut it, and you might as well try to cut a river. The blade passes; the water does not part.",
    ContentFR = "Les liens du sang sont de ces choses qu’on ne peut jamais vraiment couper. Comme lorsqu’on tente de fendre l’eau avec une lame : la coupure ne tient pas, et le courant poursuit sa course.",
    ContentJP = "血のつながり、親縁というものは、どんなに遠ざけようとしても、切れるものじゃない。刃を振るっても水は断てず、むしろ流れは深くなるばかり——",
    ContentKR = "칼로 물을 벨 수 없듯이, 천륜이란 끊으려야 끊을 수 없는 법이다.",
    ContentTC = "血緣親情，就是這樣無法割棄的東西，一如抽刀斷水，斬不斷，流更流。",
    TextMapContent = "血缘亲情，就是这样无法割弃的东西，一如抽刀断水，斩不断，流更流。",
    TextMapId = "PartyTopic_Description_150403"
  },
  PartyTopic_Description_180101 = {
    ContentEN = "She whispered her magical wishes to her friends.",
    ContentFR = "Elle confia ses souhaits magiques à ses amis.",
    ContentJP = "魔法の願いを、彼女は友達に託す。",
    ContentKR = "그녀는 친구에게 마법의 소망을 보냈다.",
    ContentTC = "她將魔法的願望寄於朋友。",
    TextMapContent = "她将魔法的愿望寄于朋友。",
    TextMapId = "PartyTopic_Description_180101"
  },
  PartyTopic_Description_180102 = {
    ContentEN = "She sent her long-lost dreams skyward upon the stars.",
    ContentFR = "Elle offrit ses rêves oubliés aux étoiles.",
    ContentJP = "彼方にある古き夢を、彼女は星々に託す。",
    ContentKR = "그녀는 높이 날아오르는 과거의 꿈을 별들에게 보냈다.",
    ContentTC = "她將高飛的故夢寄於群星。",
    TextMapContent = "她将高飞的故梦寄于群星。",
    TextMapId = "PartyTopic_Description_180102"
  },
  PartyTopic_Description_180103 = {
    ContentEN = "She buried her memories in distant lands.",
    ContentFR = "Elle enterra ses souvenirs dans des terres lointaines.",
    ContentJP = "埋もれた記憶を、彼女は彼方に託す。",
    ContentKR = "그녀는 묻어둔 추억을 멀리 보냈다.",
    ContentTC = "她將埋藏的追憶寄于遠方。",
    TextMapContent = "她将埋藏的追忆寄于远方。",
    TextMapId = "PartyTopic_Description_180103"
  },
  PartyTopic_Description_180104 = {
    ContentEN = "She entrusts her hopes for tomorrow to the blank pages.",
    ContentFR = "Elle confia ses lendemains à venir aux pages blanches.",
    ContentJP = "まだ訪れていない明日を、彼女は白いページに託す。",
    ContentKR = "그녀는 아직 오지 않은 내일을 종이에 담았다.",
    ContentTC = "她將未至的明日寄於紙頁。",
    TextMapContent = "她将未至的明日寄于纸页。",
    TextMapId = "PartyTopic_Description_180104"
  },
  PartyTopic_Description_210101 = {
    ContentEN = "Thump, thump, thump — did you hear that? It's the sound of love flowing through.",
    ContentFR = "Boum, boum... tu l’entends ? C’est le son de l’amour qui s’écoule.",
    ContentJP = "トゥクントゥクン……聞こえるかしら？愛が流れる音が。",
    ContentKR = "두근, 두근두근, 들리나요? 사랑이 흐르는 소리가.",
    ContentTC = "砰砰，砰砰，聽到了嗎，愛意流淌的聲音。",
    TextMapContent = "砰砰，砰砰，听到了吗，爱意流淌的声音。",
    TextMapId = "PartyTopic_Description_210101"
  },
  PartyTopic_Description_210102 = {
    ContentEN = "Love is meant to be tested. Rather than sweet nothings, a drop of poison feels like a far more honest trial. Whether forever apart or happily ever after — why not find out now?",
    ContentFR = "L’amour se mesure à l’épreuve. Face aux doux serments, une seule goutte de venin dit bien mieux la vérité. Soit la mort, soit l’éternité — pourquoi ne pas tenter votre chance ?",
    ContentJP = "愛には試練がつきものなの。甘い誓いよりも、一滴の毒液の方がずっと公平だと思わない？生死がふたりを分かつか、それともずっと一緒にいられるか、試してみない？",
    ContentKR = "사랑에는 항상 시련이 있어요. 달콤한 맹세보다 한 방울의 독액 같은 시련이 더욱 공정한 법이죠. 삶과 죽음을 나눠서 선택하든지, 아니면 서로 영원히 의지하는 걸 선택하면 돼요. 어때요, 한번 해 볼까요?",
    ContentTC = "愛情總會有考驗，比起甜蜜的誓言，一滴毒液的考驗顯得那麼公正。要麼生死兩隔，要麼長相廝守，何不，試上一試？",
    TextMapContent = "爱情总会有考验，比起甜蜜的誓言，一滴毒液的考验显得那么公正。要么生死两隔，要么长相厮守，何不，试上一试？",
    TextMapId = "PartyTopic_Description_210102"
  },
  PartyTopic_Description_210103 = {
    ContentEN = "Even monsters have vulnerabilities. They aren't heartless demons — just lonely misfits lost among the crowd.",
    ContentFR = "Même les monstres ont leurs failles. Ce ne sont pas des démons sans âme, seulement des êtres à part, perdus parmi les hommes.",
    ContentJP = "化け物にも弱点がある。彼らは血も涙もない悪魔ではなく、ただ群れのなかの異端者に過ぎない。",
    ContentKR = "몬스터에게도 약점이 있다. 그들은 피도 눈물도 없는 악마가 아닌, 그저 인간과는 다른 종일뿐이다.",
    ContentTC = "怪物也會有弱點，它們不是無血無淚的惡魔，只是人群中的異類。",
    TextMapContent = "怪物也会有弱点，它们不是无血无泪的恶魔，只是人群中的异类。",
    TextMapId = "PartyTopic_Description_210103"
  },
  PartyTopic_Description_210104 = {
    ContentEN = "Love is a blade that cuts through all barriers, whether across mountains, seas, or a single drop of lethal poison.",
    ContentFR = "L’amour est une lame qui tranche toutes les entraves — montagnes, océans ou poison.",
    ContentJP = "愛は幾重にも重なる障害を断ち切る鋭い刃となる。たとえ万里の隔たりがあろうとも、一滴の致命的な毒があろうとも。",
    ContentKR = "사랑은 겹겹이 쌓인 장애물을 자르는 날카로운 칼날이다. 수많은 산과 강이 가로막아도, 또 치명적인 독 한 방울이 지키고 있어도 상관없다.",
    ContentTC = "愛是斬斷層層阻礙的利刃。無論隔著萬水千山，還是隔著一滴致命的毒。",
    TextMapContent = "爱是斩断层层阻碍的利刃。无论隔着万水千山，还是隔着一滴致命的毒。",
    TextMapId = "PartyTopic_Description_210104"
  },
  PartyTopic_Description_210201 = {
    ContentEN = "To save more innocent people from the King of Paradise, a girl who isn't very good at telling stories tries her very best to write one.",
    ContentFR = "Pour sauver davantage d’innocents des mains du Roi du Paradis, la jeune fille maladroite se creuse la tête pour inventer des histoires.",
    ContentJP = "楽園の王から、より多くの罪なき人々を救うため、不器用な少女は知恵を絞りながら物語を書き綴っていた。",
    ContentKR = "낙원의 왕에게서 무고한 사람을 더 많이 구하기 위해, 서툰 소녀는 최선을 다해 이야기를 지어낸다.",
    ContentTC = "為了從樂園的國王手中救下更多無辜者，笨拙的女孩絞盡腦汁編寫著故事。",
    TextMapContent = "为了从乐园的国王手中救下更多无辜者，笨拙的女孩绞尽脑汁编写着故事。",
    TextMapId = "PartyTopic_Description_210201"
  },
  PartyTopic_Description_210202 = {
    ContentEN = "Everyone has their own idea of happiness. But when fairy tales end happily, are the people inside them truly happy too?",
    ContentFR = "Chacun a sa propre définition du bonheur. Mais ces fins heureuses imaginées par les auteurs de contes... sont-elles vraiment un bonheur pour les héros de leurs histoires ?",
    ContentJP = "幸せの定義は人それぞれ異なる。童話作家が書いた幸せな結末は、童話の主人公たちにとって本当に幸せなのだろうか？",
    ContentKR = "사람마다 행복의 기준은 다르다. 그렇다면 이야기 속 주인공은, 동화 작가가 써 준 해피 엔딩을 진정으로 행복하다고 생각할까?",
    ContentTC = "每個人對幸福的定義都不盡相同，那些由童話作者寫下的幸福結局，對於童話的主人公們來說，真的是一種幸福嗎？",
    TextMapContent = "每个人对幸福的定义都不尽相同，那些由童话作者写下的幸福结局，对于童话的主人公们来说，真的是一种幸福吗？",
    TextMapId = "PartyTopic_Description_210202"
  },
  PartyTopic_Description_210203 = {
    ContentEN = "There has never been a true paradise in this world. It is time to say goodbye.",
    ContentFR = "Il n’existe aucun véritable Paradis en ce monde. Il est temps de lui dire adieu.",
    ContentJP = "この世に本当の楽園など存在しない。もう別れを告げる時だ。",
    ContentKR = "이 세상에 진정한 낙원은 존재하지 않는다. 이제, 작별을 고할 시간이다.",
    ContentTC = "這世上從不存在真正的樂園，是時候說再見了。",
    TextMapContent = "这世上从不存在真正的乐园，是时候说再见了。",
    TextMapId = "PartyTopic_Description_210203"
  },
  PartyTopic_Description_230101 = {
    ContentEN = "Camouflage offers protection; mimicry punishes the wicked.",
    ContentFR = "La dissimulation protège, l’imitation punit.",
    ContentJP = "偽装は身を守る手段であり、擬態は悪者を罰する能力だ。",
    ContentKR = "위장은 자신을 보호하는 수단이고, 흉내는 나쁜 사람을 징벌할 수 있는 기술이다.",
    ContentTC = "偽裝是保護自身的手段，擬態是懲罰壞人的技巧。",
    TextMapContent = "伪装是保护自身的手段，拟态是惩罚坏人的技巧。",
    TextMapId = "PartyTopic_Description_230101"
  },
  PartyTopic_Description_230102 = {
    ContentEN = "Others may define good and bad, but it's up to you to decide right from wrong.",
    ContentFR = "Le bien et le mal se jugent par autrui, mais seul soi-même décide du juste et du faux.",
    ContentJP = "善悪は他人によって定義される。それが正しいか間違っているかは自分で決める。",
    ContentKR = "좋고 나쁨은 다른 사람이 정하고, 옳고 그름은 자신이 정하는 것이다.",
    ContentTC = "好壞由他人定義，對錯由自我決定。",
    TextMapContent = "好坏由他人定义，对错由自我决定。",
    TextMapId = "PartyTopic_Description_230102"
  },
  PartyTopic_Description_230103 = {
    ContentEN = "Once you open your eyes, a broader world unfolds.",
    ContentFR = "Ôtez la feuille qui vous cache les yeux, et le monde s’ouvre — plus vaste que vous ne l’imaginiez.",
    ContentJP = "目を覆う木の葉を払いのければ、もっと広い世界が見える。",
    ContentKR = "가려진 잎을 치우면 더 넓은 세상을 볼 수 있다.",
    ContentTC = "拿掉遮目的片葉，便能看到更廣闊的世界。",
    TextMapContent = "拿掉遮目的片叶，便能看到更广阔的世界。",
    TextMapId = "PartyTopic_Description_230103"
  },
  PartyTopic_Description_230104 = {
    ContentEN = "Even in chaos, there is warmth to be found.",
    ContentFR = "Même dans le chaos, on peut encore trouver une chaleur.",
    ContentJP = "混沌の坩堝（るつぼ）のなかでも、わずかなぬくもりが感じられる。",
    ContentKR = "혼돈의 온실 속에서도 온기를 느낄 수 있다.",
    ContentTC = "在混沌的溫床中，也是能體會到一絲溫暖的。",
    TextMapContent = "在混沌的温床中，也是能体会到一丝温暖的。",
    TextMapId = "PartyTopic_Description_230104"
  },
  PartyTopic_Description_240101 = {
    ContentEN = "A healer who once slumbered for a century now offers to treat your sleeplessness.",
    ContentFR = "Après un siècle de sommeil, l’ancienne guérisseuse vous propose d’apaiser vos nuits tourmentées.",
    ContentJP = "——百年の眠りから目覚めた医師が、あなたの「眠れぬ夜」に静かに寄り添おうとしている。",
    ContentKR = "기나긴 잠에서 깨어난 의원이, 내 불면증을 치료해 주려 한다.",
    ContentTC = "曆經百年沉眠的醫師，想為你治療不眠的症候。",
    TextMapContent = "历经百年沉眠的医师，想为你治疗不眠的症候。",
    TextMapId = "PartyTopic_Description_240101"
  },
  PartyTopic_Description_240102 = {
    ContentEN = "A single blade of grass may veil the eyes — and all that lies before them becomes a waking dream of what is long past.",
    ContentFR = "Une herbe suffit parfois à voiler le regard, et ce que l’on voit n’est plus que le songe éveillé d’un passé révolu.",
    ContentJP = "——たった一枚の葉が視界を覆うとき、目に映るのは、すべて過ぎ去りし日の夢ばかり。",
    ContentKR = "나뭇잎 하나가 눈을 가리니, 지나간 옛꿈만이 눈에 어리네.",
    ContentTC = "一葉障目，所見皆是過往舊夢。",
    TextMapContent = "一叶障目，所见皆是过往旧梦。",
    TextMapId = "PartyTopic_Description_240102"
  },
  PartyTopic_Description_240103 = {
    ContentEN = "You saw her, plain as day — a healer, a nonconformist, and a sister.",
    ContentFR = "Vous l’avez vue de vos propres yeux — une guérisseuse, une dissidente, une sœur.",
    ContentJP = "——あなたは、彼女の姿をこの目で見た。一人の医師。一人の「規を外れし者」。そして——一人の姉。",
    ContentKR = "실제로 만난 부풍은 의사이자, 정도를 벗어난 자였으며, 한 사람의 언니였다.",
    ContentTC = "你親眼見到了她的模樣——一位醫師，一位離經叛道者，一位姐姐。",
    TextMapContent = "你亲眼见到了她的模样——一位医师，一位离经叛道者，一位姐姐。",
    TextMapId = "PartyTopic_Description_240103"
  },
  PartyTopic_Description_240104 = {
    ContentEN = "The Hall of Ephemerality stands empty — and yet, so long as memory endures, it remains the home she holds dear.",
    ContentFR = "Le Pavillon de l’Éphémère est désormais désert. Mais tant que subsistent les souvenirs d’autrefois, il demeure encore le lieu qu’elle appelle son foyer.",
    ContentJP = "枯栄閣には誰の姿もない。だが、古き記憶が息づくかぎり、ここはきっと、彼女が懐かしむ故郷なのだろう。",
    ContentKR = "비록 고영각엔 아무도 없지만, 지난날의 추억이 머무는 한, 부소에겐 변함없이 그리운 고향으로 기억될 것이다.",
    ContentTC = "枯榮閣空無一人，唯餘舊日回憶，但只要舊日回憶仍在，那麼這裡，就仍是她所懷念的故園。",
    TextMapContent = "枯荣阁空无一人，唯余旧日回忆，但只要旧日回忆仍在，那么这里，就仍是她所怀念的故园。",
    TextMapId = "PartyTopic_Description_240104"
  },
  PartyTopic_Description_310101 = {
    ContentEN = "Life is simple — eat to live, not the other way around. Keep that straight, and you'll be fine.",
    ContentFR = "Vivre, c’est manger. Tant que vous savez manger pour vivre — et pas vivre seulement pour manger — ça ira.",
    ContentJP = "生きるためには食べなければならない。食べるために生きるのではなく、生きるために食べるといく認識が大切だ。",
    ContentKR = "사람이 살아가려면 밥을 먹어야 한다. 살기 위해 밥을 먹는 것이지, 밥을 먹기 위해 사는 것이 아니다.",
    ContentTC = "人活著就得吃飯，拎得清吃飯是為了活著，而不是活著為了吃飯就行。",
    TextMapContent = "人活着就得吃饭，拎得清吃饭是为了活着，而不是活着为了吃饭就行。",
    TextMapId = "PartyTopic_Description_310101"
  },
  PartyTopic_Description_310102 = {
    ContentEN = "There's something almost magical about high voltage — it dares you to flirt with danger and uncover its risky secrets.",
    ContentFR = "Il y a dans la haute tension une sorte de magie : elle vous attire, vous frôle, vous défie de toucher le danger pour en percer le secret.",
    ContentJP = "高電圧にはなにか不思議な魔力が宿っているようだ。少しだけなら大丈夫だろうと思って、つい危険な境界を探ってしまう。",
    ContentKR = "고압전기는 신기한 마력을 가지고 있어 사람들은 그 가장자리를 반복적으로 탐색하며 그 속에 숨겨진 위험한 비밀들을 찾고자 한다.",
    ContentTC = "高壓電有種神奇的魔力，它吸引著人們在其邊緣反復試探，不斷探尋那些危險的秘密。",
    TextMapContent = "高压电有种神奇的魔力，它吸引着人们在其边缘反复试探，不断探寻那些危险的秘密。",
    TextMapId = "PartyTopic_Description_310102"
  },
  PartyTopic_Description_310103 = {
    ContentEN = "More sorrowful than losing one's home is seeing it intact but forever out of reach.",
    ContentFR = "Plus cruel que perdre sa maison : la voir encore là, intacte... et savoir qu’on ne pourra jamais y revenir.",
    ContentJP = "故郷を失うことよりも辛いのは、家はすぐそこにあるのに、越えられない壁がそびえ立っていることだ。",
    ContentKR = "고향을 잃은 것보다 더 슬픈 것은 집이 바로 그곳에 있는데, 그 가운데에 넘을 수 없는 벽이 가로놓여 있다는 것이다.",
    ContentTC = "比失去家鄉更悲哀的是，家就在那裡，中間卻橫亙著無法逾越的障壁。",
    TextMapContent = "比失去家乡更悲哀的是，家就在那里，中间却横亘着无法逾越的障壁。",
    TextMapId = "PartyTopic_Description_310103"
  },
  PartyTopic_Description_310201 = {
    ContentEN = "A maid's duties cover every aspect of life — including a few that might involve a bit of... bloodshed.",
    ContentFR = "Le rôle d’une servante couvre chaque aspect du quotidien — y compris, à l’occasion, des tâches qui laissent des taches de sang.",
    ContentJP = "日常生活のあらゆる面に気を配るのはメイドの職務である。時には血を浴びることもやむを得ない。",
    ContentKR = "메이드는 일상생활의 모든 것을 챙겨야 한다. 약간의 '피를 묻히는' 일도 포함될 수 있다.",
    ContentTC = "女僕需要打點日常生活的方方面面，包括但不限於一點點「沾血」的工作。",
    TextMapContent = "女仆需要打点日常生活的方方面面，包括但不限于一点点“沾血”的工作。",
    TextMapId = "PartyTopic_Description_310201"
  },
  PartyTopic_Description_310202 = {
    ContentEN = "First impressions matter, and nothing speaks more directly than what you wear. Fashion, after all, is a timeless art.",
    ContentFR = "On dit que la première impression décide de tout. Et la première impression, le plus souvent, c’est ce que vous portez. S’habiller, c’est une discipline qui ne vieillit jamais.",
    ContentJP = "「第一印象が重要だ」とよく言われるが、その最初の印象を決めるのは服装である。そして、コーディネートは永遠に答えのでない学問だ。",
    ContentKR = "사람들은 흔히 첫인상이 중요하다고 말한다. 가장 직접적인 첫인상은 옷차림에서 비롯된다. 옷차림은 일종의 영원한 학문인 것이다.",
    ContentTC = "人們常說第一印象很重要，最直接的第一印象來自服飾穿搭——而穿搭，則是一門永恆的學問。",
    TextMapContent = "人们常说第一印象很重要，最直接的第一印象来自服饰穿搭——而穿搭，则是一门永恒的学问。",
    TextMapId = "PartyTopic_Description_310202"
  },
  PartyTopic_Description_310203 = {
    ContentEN = "Snip, snip. Trim the flowers, and with them, trim away the woes.",
    ContentFR = "Clic. Clic. Les ciseaux tranchent les fleurs fanées — et un peu des soucis du cœur.",
    ContentJP = "パチン、パチン。花の枝を切り落とし、悩みを断ち切る。",
    ContentKR = "싹둑, 싹둑. 꽃가지를 잘라내면 고민도 잘려나간다.",
    ContentTC = "哢嚓、哢嚓。剪去花枝，剪去煩惱。",
    TextMapContent = "咔嚓、咔嚓。剪去花枝，剪去烦恼。",
    TextMapId = "PartyTopic_Description_310203"
  },
  PartyTopic_Description_310204 = {
    ContentEN = "No matter how well you hide, \"growing up\" always finds a way to catch up with you.",
    ContentFR = "On a beau se cacher dans le moindre recoin... « grandir » finit toujours par nous retrouver.",
    ContentJP = "どんなに目立たない片隅に身を隠したとしても、「成長」はいずれ私たちに追いつき、私たちを見出す。",
    ContentKR = "어디에 어떻게 숨어도 '성장'은 항상 우릴 뒤쫓고, 결국 찾아낸다.",
    ContentTC = "無論把自己藏在怎樣隱蔽的小角落，「成長」總會追上我們，找到我們。",
    TextMapContent = "无论把自己藏在怎样隐蔽的小角落，“成长”总会追上我们，找到我们。",
    TextMapId = "PartyTopic_Description_310204"
  },
  PartyTopic_Description_310301 = {
    ContentEN = "Everything he says circles back to explosions — that's one explosive way to make a first impression.",
    ContentFR = "Il ne parle que d’explosifs et d’étincelles. C’est une façon... percutante de se présenter.",
    ContentJP = "何度も爆発って言葉を繰り返すなんて、正に炸裂したオープニングトークだ。",
    ContentKR = "말 세 마디마다 폭발 이야기가 빠지지 않는 것도 강렬한 소개법이다.",
    ContentTC = "三句話離不開爆炸，也是一種炸裂的開場介紹。",
    TextMapContent = "三句话离不开爆炸，也是一种炸裂的开场介绍。",
    TextMapId = "PartyTopic_Description_310301"
  },
  PartyTopic_Description_310302 = {
    ContentEN = "An unexpected visit, a conflicted conversation.",
    ContentFR = "Une visite qui tombe sans prévenir. Une conversation qui ne tombe pas juste.",
    ContentJP = "突然の訪問、矛盾する対話。",
    ContentKR = "갑작스러운 단독 방문, 모순된 대화.",
    ContentTC = "一次突兀的獨訪，一場矛盾的對話。",
    TextMapContent = "一次突兀的独访，一场矛盾的对话。",
    TextMapId = "PartyTopic_Description_310302"
  },
  PartyTopic_Description_310303 = {
    ContentEN = "They may be sworn enemies, but also inseparable halves of the same whole.",
    ContentFR = "Parfois, « l’ennemi juré » n’est qu’une autre moitié de soi.",
    ContentJP = "相容れない「敵」であると同時に、一生離れられない「分身」でもある。",
    ContentKR = "용납할 수 없는 '적'이자 떼어낼 수 없는 '반쪽'.",
    ContentTC = "無法相容的「敵人」，也是不可分割的「半身」。",
    TextMapContent = "无法兼容的“敌人”，也是不可分割的“半身”。",
    TextMapId = "PartyTopic_Description_310303"
  },
  PartyTopic_Description_310304 = {
    ContentEN = "Trapped in darkness, the warmth they share is the only light that dispels the gloom.",
    ContentFR = "Prisonniers d’une même nuit, ils n’avaient qu’une seule chandelle : la chaleur de l’autre.",
    ContentJP = "暗闇に囚われた囚人同士が、互いに触れ合うその温もりこそ、闇を晴らす灯火となる。",
    ContentKR = "같은 어둠 속에 갇혀 있는 죄수들에게는 서로의 온기가 이 어둠을 몰아내는 등불이 된다.",
    ContentTC = "困在同一片黑暗之中的囚徒，只有彼此的溫度，才是驅散這片黑暗的燈火。",
    TextMapContent = "困在同一片黑暗之中的囚徒，只有彼此的温度，才是驱散这片黑暗的灯火。",
    TextMapId = "PartyTopic_Description_310304"
  },
  PartyTopic_Description_310401 = {
    ContentEN = "A soldier has only one rule: obey orders.",
    ContentFR = "Obéir aux ordres est la seule règle qu’un soldat doit suivre.",
    ContentJP = "命令に従うこと、それが軍人にとって唯一の鉄則。",
    ContentKR = "군인이 따라야 할 원칙은 오직 명령에 복종하는 것뿐이다.",
    ContentTC = "服從命令，是軍人的唯一準則。",
    TextMapContent = "服从命令，是军人的唯一准则。",
    TextMapId = "PartyTopic_Description_310401"
  },
  PartyTopic_Description_310402 = {
    ContentEN = "You placed your soul on the scales and learned what your life was worth: one medal on the other pan. No more, no less. The scales balanced.",
    ContentFR = "Tu n’as compris le poids de toute une vie qu’en plaçant ton âme sur une balance. Sur l’autre plateau reposait une médaille. Ni plus, ni moins. Son poids était exactement celui de ton existence.",
    ContentJP = "あなたは魂を天秤に載せて初めて、自らの生涯の重みを知った。天秤のもう一方に載せられた一つの勲章。それは多くも少なくもなく、あなたが歩んできた人生そのものの重さだった。",
    ContentKR = "어떤 삶을 살아왔는지는 저울에 영혼을 올리고 나서야 가늠할 수 있다. 정확히 균형을 이루는 저울 반대편에 놓인 훈장 하나. 많지도 적지도 않은 그 정도가, 바로 당신이 걸어온 삶의 무게다.",
    ContentTC = "你將靈魂放在了天平上，才知道自己這一生的斤兩：天平的另一端稱量一枚勳章，這些正好，不多不少，是你走過的生命所擁有的重量。",
    TextMapContent = "你将灵魂放在了天平上，才知道自己这一生的斤两：天平的另一端称量一枚勋章，这些正好，不多不少，是你走过的生命所拥有的重量。",
    TextMapId = "PartyTopic_Description_310402"
  },
  PartyTopic_Description_310403 = {
    ContentEN = "This is his rage. Hers, too. Theirs. Hatred, despair, and one last act of desperation, all burning together into a fire that will not die.",
    ContentFR = "La colère était la sienne. Elle était aussi la leur. Née de la haine, du désespoir et d’un dernier pari sans retour, elle brûlait comme un feu ardent, inextinguible et éternel.",
    ContentJP = "これは彼の怒りであり、彼女の、そして彼らの怒りでもある。憎しみと絶望、捨て身の覚悟の末に生まれたもの。それは激しく、尽きることなく、決して消えない炎だ。",
    ContentKR = "이것은 그의 분노이자, 그녀의 분노이며, 그들 모두의 분노이다. 증오와 절망, 그리고 모든 것을 내던진 결과이자, 영원토록 사그라지지 않고 거세게 타오르는 불길이다.",
    ContentTC = "這是他的憤怒，也是她的、他們的憤怒。它是憎恨、絕望、孤注一擲的結果，它是熾烈的、無窮的、不死的火。",
    TextMapContent = "这是他的愤怒，也是她的、他们的愤怒。它是憎恨、绝望、孤注一掷的结果，它是炽烈的、无穷的、不死的火。",
    TextMapId = "PartyTopic_Description_310403"
  },
  PartyTopic_Description_320101 = {
    ContentEN = "A haunted house, a guest with secrets, and an amateur bartender.",
    ContentFR = "Une maison hantée, une cliente aux identités multiples... et {性别:un barman|une barmaid} un peu novice.",
    ContentJP = "幽霊屋敷、別の顔を持つ酒客、そして中途半端なバーテンダー。",
    ContentKR = "귀신 들린 집, 신분을 감춘 술꾼, 어설픈 바텐더.",
    ContentTC = "鬼宅，另有身份的酒客，半吊子的調酒師。",
    TextMapContent = "鬼宅，另有身份的酒客，半吊子的调酒师。",
    TextMapId = "PartyTopic_Description_320101"
  },
  PartyTopic_Description_320102 = {
    ContentEN = "A strong spirit distilled from concentrated botanical extracts. Despite the name, its flavour is far from purely bitter — it's layered, evolving, and surprisingly complex.",
    ContentFR = "Un alcool fort infusé d’essences végétales. Malgré son nom, son goût n’a rien d’une amertume simple ou uniforme : il est complexe, changeant, presque insaisissable.",
    ContentJP = "実際には、植物のエキスを濃縮して作られた高アルコールの酒であり、「ビターズ」と呼ばれてはいるものの、その味わいは単純な苦味にとどまらず、より複雑で多彩な風味を持つ。",
    ContentKR = "실제로는 식물 엑기스를 농축한 독한 술이다. 쓴맛이라고 불리지만 철저하고 단조로운 쓴맛이 아니라 더욱 복잡하고 변화무쌍하다.",
    ContentTC = "實際上是濃縮了植物精華的烈酒，雖然被稱為苦精，但並不是徹底而單調的苦味，嚐起來更加複雜與多變。",
    TextMapContent = "实际上是浓缩了植物精华的烈酒，虽然被称为苦精，但并不是彻底而单调的苦味，尝起来更加复杂与多变。",
    TextMapId = "PartyTopic_Description_320102"
  },
  PartyTopic_Description_320103 = {
    ContentEN = "Craving sweetness is instinctual — people are drawn, often unconsciously, to memories of joy and warmth, even if overindulgence may take its toll on the body.",
    ContentFR = "La passion du sucre est instinctive : l’être humain cherche sans même s’en rendre compte à retrouver la douceur de ses souvenirs heureux... même si l’excès lui coûte cher.",
    ContentJP = "甘いものを求めるのは本能だ。人は無意識のうちに、楽しかった記憶や甘美な思い出にすがろうとする。……たとえ、それが身体にとって危うい代物だとしても。",
    ContentKR = "단 것을 좋아하는 것은 본능이다. 인간은 무의식적으로 즐겁고 달콤한 기억을 그리워하기 때문이다. ...단, 과도한 섭취는 몸에 큰 위험을 초래할 것이다.",
    ContentTC = "嗜糖是一種本能，因為人總是下意識地留戀快樂與甜蜜的回憶，儘管過度攝入對身體大有風險。",
    TextMapContent = "嗜糖是一种本能，因为人总是下意识地留恋快乐与甜蜜的回忆，尽管过度摄入对身体大有风险。",
    TextMapId = "PartyTopic_Description_320103"
  },
  PartyTopic_Description_320104 = {
    ContentEN = "It burns down the throat like a blade — and only the drinker knows what it cuts open inside.",
    ContentFR = "Il brûle la gorge comme une lame — et seuls ceux qui le boivent savent ce qu’il vient ouvrir au fond d’eux.",
    ContentJP = "まるで刃のように喉を滑り、飲んだ者だけがその先に何を切り裂いたのかを知る。",
    ContentKR = "칼날처럼 목구멍 속을 흐른다. 그 칼날에 베인 게 무엇인지는 마신 이만 알 수 있다.",
    ContentTC = "像刀子一樣滾過喉嚨，只有喝下的人才知道它剖開了些什麼。",
    TextMapContent = "像刀子一样滚过喉咙，只有喝下的人才知道它剖开了些什么。",
    TextMapId = "PartyTopic_Description_320104"
  },
  PartyTopic_Description_320201 = {
    ContentEN = "Today only at The Asphodel: 20% off all drinks! Charon or not — everyone gets the discount!",
    ContentFR = "Aujourd’hui aux Asphodèles : promotion spéciale — toutes les boissons à –20 % ! Même les Charon peuvent en profiter !",
