  PermanentRepeatDungeon01_Des = {
    ContentEN = "Mistwharf is Haojing's largest shipping port and the main hub through which Starweavers enter and depart Huaxu.",
    ContentFR = "Plus grand port de transport de Haojing, Port-des-Brumes constitue également le principal point de passage des Tisse-Étoiles entrant et sortant de Huaxu.",
    ContentJP = "<up text=\"えんしんと\">煙津渡</>は<up text=\"こうけい\">皓京</>最大の輸送<up text=\"さんばし\">桟橋</>であり、星織人たちが<up text=\"カショ\">華胥</>へ出入りする際の最初の関門でもあります。",
    ContentKR = "연진 나루터는 호경에서 가장 큰 운송 부두이자, 별을 잇는 자들이 화서를 드나드는 첫 번째 관문이며 요충지다.",
    ContentTC = "煙津渡作為皓京最大的運輸碼頭，也是織星客們進出華胥的首要關卡樞紐。",
    TextMapContent = "烟津渡作为皓京最大的运输码头，也是织星客们进出华胥的首要关卡枢纽。",
    TextMapId = "PermanentRepeatDungeon01_Des"
  },
  PermanentRepeatDungeon01_Title = {
    ContentEN = "Mistwharf",
    ContentFR = "Port-des-Brumes",
