  QuestDesc__10020611_1 = {
    ContentEN = "Psyche has given you the camera as a gift. Capture this moment with it.",
    ContentFR = "Psyche vous a offert un appareil photo en cadeau. Utilisez-le pour graver cet instant dans la mémoire.",
    ContentJP = "サイキからの贈り物を受け取ったら、カメラでその瞬間を記録しよう。",
    ContentKR = "프시케가 준 선물을 받았다. 사진기로 이 순간을 기록해 보자.",
