  QuestMutualExclusion_Content_1002 = {
    ContentEN = "Separated from Berenica and cast into the sea, {nickname} was rescued by a mysterious figure in white and taken to Icelake, a city in northern Hyperborea...",
    ContentFR = "Après avoir été séparé de Berenica et être tombé dans la mer, {nickname} est {性别:sauvé|sauvée} par l’Inconnu en blanc, puis conduit à Givrelac, une ville située au nord d’Hyperborea...",
    ContentJP = "ベレニカと別れ、海へ落ちた後、{nickname}は白衣の謎の人物に救われ、その後ヒュペリア北方の都市――アイスレイク城へと連れていかれた……",
    ContentKR = "베레니카와 헤어져 바다에 빠진 {nickname}은(는) 이후 흰 옷을 입은 수수께끼의 인물에게 구조되어 휘페르보레아 북부의 도시인 아이스레이크 시티로 오게 된다...",
    ContentTC = "與貝蕾妮卡分別並墜入大海後，{nickname}被一位白衣神秘人救下，隨後被帶到海伯利亞北境城市——冰湖城……",
    TextMapContent = "与贝蕾妮卡分别并坠入大海后，{nickname}被一位白衣神秘人救下，随后被带到海伯利亚北境城市——冰湖城……",
    TextMapId = "QuestMutualExclusion_Content_1002"
  },
  QuestMutualExclusion_Content_1003 = {
    ContentEN = "In the dead of night, a grotesque creature stalked the streets of Icelake. Seeking the truth behind the tragedy known as the Charon Hunt, the Noctoyagers accepted a request from Rhythm, a junior officer in the Icelake Escort...",
    ContentFR = "Au cœur de la nuit, une créature terrifiante a commencé sa chasse dans Givrelac. Afin d’enquêter sur la vérité derrière la tragédie de la Traque aux Charons, les Vagabonds de la Nuit ont accepté la requête de Rhythm, adjudante des Veilleurs...",
    ContentJP = "夜の奥深く、アイスレイク城で恐ろしい怪物が狩りを始めた。「カロン狩り」という惨劇の真相を調査するため、「ノクトボイジャー」は警備部隊の下級士官――リズムの依頼を引き受けた……",
    ContentKR = "칠흑 같은 밤, 끔찍한 괴물이 아이스레이크 시티에서 사냥에 나선다. 팀 '녹토 보이저'는 '카론 사냥'이라는 참극의 진상을 파헤치기 위해 방위대 소속 리듬 준위의 의뢰를 받아들인다.",
    ContentTC = "於夜色深處，一隻可怖的怪物在冰湖城展開了它的狩獵。為了調查「卡戎狩獵」這一慘案的真相，夜航者小隊接下了衛戍部隊下級軍官——黎瑟的委託……",
    TextMapContent = "于夜色深处，一只可怖的怪物在冰湖城展开了它的狩猎。为了调查“卡戎狩猎”这一惨案的真相，夜航者小队接下了卫戍部队下级军官——黎瑟的委托……",
    TextMapId = "QuestMutualExclusion_Content_1003"
  },
  QuestName_10020101 = {
    ContentEN = "Follow Snow to Icelake",
    ContentFR = "Suivre Snow jusqu’à Givrelac",
    ContentJP = "スノウと共にアイスレイク城へ向かう",
    ContentKR = "스노우를 따라 아이스레이크 시티로 이동",
    ContentTC = "跟隨白前往冰湖城",
    TextMapContent = "跟随白前往冰湖城",
