  RESOURCE_DESC_12001 = {
    ContentEN = "Crafted with precision from the blueprint of Ingenious Tactics. As the component closest to the wielder, the essence of its design is to ensure optimal handling.",
    ContentFR = "Conçu avec une précision absolue selon les plans de Stratagème habile.\nPartie la plus proche de son porteur, son unique vocation est d’offrir une prise parfaitement équilibrée.",
    ContentJP = "設計図に基づき製造された「ストラタジャム」のパーツ。使用者が一番よく触れる部分で、「使いやすさ」を最優先に設計されている。",
    ContentKR = " \n도면대로 정확히 제작한 기발한 전술 부품. 사용자의 편의성을 위해 실질적인 설계 목적을 갖고 만들어졌다.",
    ContentTC = "嚴格按照圖紙打造的慧謀的攻守部件。冷兵器上最貼近使用者的部分，「趁手」，是它最實際的設計目的。",
    TextMapContent = "严格按照图纸打造的慧谋的攻守部件。冷兵器上最贴近使用者的部分，“趁手”，是它最实际的设计目的。",
    TextMapId = "RESOURCE_DESC_12001"
  },
  RESOURCE_DESC_12002 = {
    ContentEN = "Crafted with precision from the blueprint of Ingenious Tactics. Whether the blade is curved or straight, light or heavy, its edge is honed exclusively for battle.",
    ContentFR = "Forgée selon les plans de Stratagème habile, sa lame — qu’elle soit courbe ou droite, légère ou massive — n’a été créée que pour le combat.",
    ContentJP = "設計図に基づき製造された「ストラタジャム」のパーツ。まっすぐであろうと、弧を描いていようと、重かろうが軽かろうが、すべての鋭い刃は戦いのために生まれた。",
    ContentKR = "도면대로 정확히 제작한 기발한 전술 부품. 칼날의 휘어진 정도나 무게는 신경 쓰지 않고, 전투를 위한 서슬 퍼런 칼날을 만들었다.",
    ContentTC = "嚴格按照圖紙打造的慧謀的攻守部件。無論刀刃是曲是直，是輕是重，它的鋒芒都只為戰鬥而生。",
    TextMapContent = "严格按照图纸打造的慧谋的攻守部件。无论刀刃是曲是直，是轻是重，它的锋芒都只为战斗而生。",
    TextMapId = "RESOURCE_DESC_12002"
  },
  RESOURCE_DESC_12003 = {
