  RESOURCE_DESC_12133 = {
    ContentEN = "Crafted with precision from the blueprint of Dove of Tomorrow. As the component closest to the wielder, the essence of its design is to ensure optimal handling.",
    ContentFR = "Conçu selon les plans de la Messagère de l’avenir, ce manche épouse naturellement la main de son porteur — une prise sûre, pensée pour accompagner chaque mouvement.",
    ContentJP = "設計図に基づき製造された「パロマ‐デ‐フトゥロ」のパーツ。使用者が一番よく触れる部分で、「使いやすさ」を最優先に設計されている。",
    ContentKR = "도면대로 정확히 제작한 미래의 비둘기 부품. 사용자의 편의성을 위해 실질적인 설계 목적을 갖고 만들어졌다.",
    ContentTC = "嚴格依照圖紙打造的「未來之鴿」部件。冷兵器中最貼近使用者的部分，「趁手」是它最實際的設計目的。   ",
    TextMapContent = "严格按照图纸打造的未来之鸽部件。冷兵器上最贴近使用者的部分，“趁手”，是它最实际的设计目的。",
    TextMapId = "RESOURCE_DESC_12133"
  },
  RESOURCE_DESC_12134 = {
    ContentEN = "Crafted with precision from the blueprint of Dove of Tomorrow. Whether the blade is curved or straight, light or heavy, its edge is honed exclusively for battle.",
    ContentFR = "Forgée selon les plans de la Messagère de l’avenir, cette lame n’existe que pour le combat, qu’elle soit courbe ou droite, légère ou massive.",
    ContentJP = "設計図に基づき製造された「パロマ‐デ‐フトゥロ」のパーツ。まっすぐであろうと、弧を描いていようと、重かろうが軽かろうが、すべての鋭い刃は戦いのために生まれた。",
    ContentKR = "도면대로 정확히 제작한 미래의 비둘기 부품. 칼날의 휘어진 정도나 무게는 신경 쓰지 않고, 전투를 위한 서슬 퍼런 칼날을 만들었다.",
    ContentTC = "嚴格依照圖紙打造的「未來之鴿」部件。無論刀刃是曲是直、是輕是重，其鋒芒皆為戰鬥而生。",
    TextMapContent = "严格按照图纸打造的未来之鸽部件。无论刀刃是曲是直，是轻是重，它的锋芒都只为战斗而生。",
