  RESOURCE_DESC_12168 = {
    ContentEN = "Crafted with precision from the blueprint of Obsidian Heart-Reaper. As the component closest to the wielder, the essence of its design is to ensure optimal handling.",
    ContentFR = "Conçue selon les plans de la Faucheuse d’obsidienne, cette poignée assure une prise ferme et naturelle — pensée pour offrir un contrôle absolu à son porteur.",
    ContentJP = "設計図に基づき製造された「オブシディアンリッパー」のパーツ。使用者が一番よく触れる部分で、「使いやすさ」を最優先に設計されている。",
    ContentKR = "도면대로 정확히 제작한 관통의 옵시디언 낫 부품. 사용자의 편의성을 위해 실질적인 설계 목적을 갖고 만들어졌다.",
    ContentTC = "嚴格按照圖紙打造的錐心黑曜鐮部件。冷兵器上最貼近使用者的部分，「趁手」，是它最實際的設計目的。",
    TextMapContent = "严格按照图纸打造的锥心黑曜镰部件。冷兵器上最贴近使用者的部分，“趁手”，是它最实际的设计目的。",
    TextMapId = "RESOURCE_DESC_12168"
  },
  RESOURCE_DESC_12169 = {
    ContentEN = "Crafted with precision from the blueprint of Obsidian Heart-Reaper. Whether the blade is curved or straight, light or heavy, its edge is honed exclusively for battle.",
    ContentFR = "Forgée selon les plans de la Faucheuse d’obsidienne, cette lame est née pour faucher ses ennemis — qu’elle soit légère ou massive, droite ou courbe, rien ne résiste à son tranchant.",
    ContentJP = "設計図に基づき製造された「オブシディアンリッパー」のパーツ。まっすぐであろうと、弧を描いていようと、重かろうが軽かろうが、すべての鋭い刃は戦いのために生まれた。",
    ContentKR = "도면대로 정확히 제작한 관통의 옵시디언 낫 부품. 칼날의 휘어진 정도나 무게는 신경 쓰지 않고, 전투를 위한 서슬 퍼런 칼날을 만들었다.",
