  RESOURCE_DESC_3000025 = {
    ContentEN = "A potion commonly used by alchemists, with a pungent, acidic smell.",
    ContentFR = "Solution alchimique couramment utilisée par les alchimistes, à l’odeur acide particulièrement agressive.",
    ContentJP = "錬金術師たちがよく使う薬。鼻をつく酸っぱい匂いがする。",
    ContentKR = "연금술사들이 자주 사용하는 약제. 코를 찌르는 신맛이 난다.",
