  RESOURCE_DESC_41009 = {
    ContentEN = "Habitual gestures often reveal what lies beneath the mind.",
    ContentFR = "Les gestes instinctifs révèlent souvent ce qui dort au fond de l’esprit.",
    ContentJP = "習慣的な所作こそ、人の深層意識の写し鏡であることが多い。",
    ContentKR = "무심코 반복하는 행동이야말로, 사람의 가장 깊은 내면을 비추는 거울이다.",
    ContentTC = "習慣性的動作，往往才是人們深層意識的寫照。",
