  RESOURCE_DESC_41011 = {
    ContentEN = "Help! The bed refuses to let me go.",
    ContentFR = "À l’aide... ce lit refuse de me libérer.",
    ContentJP = "助けて、ベッドに捕まった。",
    ContentKR = "으악, 침대에게 붙잡혔다.",
