  RLBlessingGroup_Desc_102 = {
    ContentEN = "[Molten Blaze] deals <Highlight>35%</> of Character ATK as periodic damage every <Highlight>1</>s.",
    ContentFR = "[Flammes ardentes] inflige des Dégâts sur la durée équivalents à <Highlight>35 %</> de l’ATQ du personnage chaque <Highlight>1</> s.",
    ContentJP = "「熔炎」は<Highlight>1</>秒ごとに対象へキャラ攻撃の<Highlight>35%</>の持続ダメージを与える。",
    ContentKR = "[염화]가 <Highlight>1</>초마다 대상에게 캐릭터 공격력 <Highlight>35%</>의 지속 대미지를 입힌다.",
    ContentTC = "[熔炎]每<Highlight>1</>秒可對目標造成<Highlight>35%</>角色攻擊的持續傷害。",
