  RLBlessing_Desc_206 = {
    ContentEN = "If enemies are within <Highlight>20</>m and Phase III is active, increases Character ATK by <Highlight>$1</>; otherwise, increases Character ATK by <Highlight>$2</>.",
    ContentFR = "Si des ennemis se trouvent dans un rayon de <Highlight>20</> m, augmente l’ATQ du personnage de <Highlight>$1</> si l’effet [III] est actif, sinon l’ATQ augmente de <Highlight>$2</>.",
