  RLBlessing_Desc_712 = {
    ContentEN = "Your Damage Taken per hit will not exceed <Highlight>#1</> Max HP. After taking damage exceeding <Highlight>$2</> Max HP, restores <Highlight>$1</> Max HP per second for <Highlight>$3</>s.",
    ContentFR = "Les dégâts reçus par coup ne peuvent excéder <Highlight>#1</> des PV max.\nAprès avoir subi des dégâts supérieurs à <Highlight>$2</> des PV max, restaure <Highlight>$1</> des PV max par seconde pendant <Highlight>$3</> s.",
    ContentJP = "1回の被ダメージは自身最大HPの<Highlight>#1</>を超えない。最大HPの<Highlight>$2</>を超えるダメージを受けた場合、<Highlight>$3</>秒間、毎秒最大HPの<Highlight>$1</>を回復。",
    ContentKR = "한 번에 받는 대미지가 자신 최대 HP의 <Highlight>#1</>을(를) 초과하지 않는다. 최대 HP의 <Highlight>$2</>보다 많은 대미지를 받을 경우, <Highlight>$3</>초 동안 매초 최대 HP의 <Highlight>$1</>만큼 회복한다.",
    ContentTC = "受到的單次傷害不會高於自身最大生命的<Highlight>#1</>，受到超過最大生命<Highlight>$2</>的傷害後<Highlight>$3</>秒內，每秒回復最大生命<Highlight>$1</>的生命。",
    TextMapContent = "受到的单次伤害不会高于自身最大生命的<Highlight>#1</>，受到超过最大生命<Highlight>$2</>的伤害后<Highlight>$3</>秒内，每秒回复最大生命<Highlight>$1</>的生命。",
    TextMapId = "RLBlessing_Desc_712"
  },
  RLBlessing_Desc_713 = {
    ContentEN = "Ultimate consumes all DEF, converting <Highlight>$1</> of it into Character ATK for <Highlight>$2</>s. This effect can only be triggered once every <Highlight>$3</>s on the same target.",
    ContentFR = "Lors de l’utilisation d’une Compétence ultime, la DÉF est entièrement consommée, puis <Highlight>$1</> de cette valeur est converti en ATQ du personnage pendant <Highlight>$2</> s.\nCet effet ne peut se déclencher qu’une fois toutes les <Highlight>$3</> s.",
    ContentJP = "「必殺技」を発動する時、防御を全て失い、失った値の<Highlight>$1</>を攻撃力に変換、<Highlight>$2</>秒継続。この効果は<Highlight>$3</>秒ごとに1回のみ発動できる。",
    ContentKR = "[종결 스킬] 시전 시 모든 방어력을 잃고 해당 수치의 <Highlight>$1</>을(를) 캐릭터 공격으로 전환한다. 지속 시간 <Highlight>$2</>초. 해당 효과는 <Highlight>$3</>초마다 최대 1회 발동한다.",
    ContentTC = "釋放[終結技]時，失去全部防禦，將失去值的<Highlight>$1</>轉化為角色攻擊，持續<Highlight>$2</>秒，效果每<Highlight>$3</>秒最多觸發1次。",
    TextMapContent = "释放[终结技]时，失去全部防御，将失去值的<Highlight>$1</>转化为角色攻击，持续<Highlight>$2</>秒，效果每<Highlight>$3</>秒最多触发1次。",
    TextMapId = "RLBlessing_Desc_713"
  },
  RLBlessing_Desc_714 = {
    ContentEN = "When dealing Skill DMG, ignore the target's DEF by <Highlight>$2</> when HP is below <Highlight>100%</> and by <Highlight>$1</> when HP is <Highlight>100%</>.",
    ContentFR = "Lorsque les PV sont inférieurs à <Highlight>100 %</>, les Dégâts de compétence ignorent <Highlight>$2</> de la DÉF de la cible.\nLorsque les PV sont à <Highlight>100 %</>, ils ignorent <Highlight>$1</> de la DÉF.",
    ContentJP = "HP割合が<Highlight>100%</>未満の場合、スキルダメージが目標の防御を<Highlight>$2</>無視する。HP割合が<Highlight>100%</>の場合、スキルダメージが目標の防御を<Highlight>$1</>無視する。",
    ContentKR = "HP 비율이 <Highlight>100%</> 미만일 때, 스킬 대미지는 대상의 <Highlight>$2</>의 방어를 무시한다. HP 비율이 <Highlight>100%</>일 때, 스킬 대미지는 대상의 <Highlight>$1</>의 방어를 무시한다.",
    ContentTC = "生命值百分比小於<Highlight>100%</>時，技能傷害無視目標<Highlight>$2</>防禦；生命值百分比為<Highlight>100%</>時，技能傷害無視目標<Highlight>$1</>防禦。",
    TextMapContent = "生命值百分比小于<Highlight>100%</>时，技能伤害无视目标<Highlight>$2</>防御；生命值百分比为<Highlight>100%</>时，技能伤害无视目标<Highlight>$1</>防御。",
    TextMapId = "RLBlessing_Desc_714"
  },
  RLBlessing_Desc_715 = {
    ContentEN = "Increases Resolve by <Highlight>$2</> when HP is below <Highlight>40%</> and by <Highlight>$1</> when HP equal to or above <Highlight>40%</>.",
    ContentFR = "Augmente la Ténacité de <Highlight>$2</> lorsque les PV sont inférieurs à <Highlight>40 %</>, ou de <Highlight>$1</> lorsque les PV sont supérieurs ou égaux à <Highlight>40 %</>.",
    ContentJP = "HP割合が<Highlight>40%</>未満の場合、背水が<Highlight>$2</>アップする。HP割合が<Highlight>40%</>以上の場合、背水が<Highlight>$1</>アップする。",
    ContentKR = "HP 비율이 <Highlight>40%</> 미만일 때, 필사가 <Highlight>$2</> 상승한다. HP 비율이 <Highlight>40%</> 이상일 때, 필사가 <Highlight>$1</> 상승한다.",
    ContentTC = "生命值百分比小於<Highlight>40%</>時，背水提高<Highlight>$2</>；生命值百分比大於等於<Highlight>40%</>時，背水提高<Highlight>$1</>。",
    TextMapContent = "生命值百分比小于等于<Highlight>40%</>时，背水提高<Highlight>$2</>；生命值百分比大于<Highlight>40%</>时，背水提高<Highlight>$1</>。",
    TextMapId = "RLBlessing_Desc_715"
  },
