    ContentJP = "一度に受けるダメージを制限し、高ダメージを受けた後に持続的にHP回復。",
    ContentKR = "자신이 1회에 받는 대미지를 제한하고, 높은 대미지를 받은 후, 지속적으로 HP 회복",
    ContentTC = "限製自身受到的單次傷害，受到高額傷害後，持續回復生命。",
    TextMapContent = "限制自身受到的单次伤害，受到高额伤害后，持续回复生命。",
    TextMapId = "RLBlessing_SimpleDesc_712"
  },
  RLBlessing_SimpleDesc_713 = {
    ContentEN = "Using an Ultimate consumes all DEF to boost Character ATK.",
    ContentFR = "Lors de l’activation de la compétence ultime, toute la DÉF est consommée et convertie en ATQ.",
    ContentJP = "「必殺技」を発動する時、防御を全て失い、攻撃力に変換。",
    ContentKR = "[종결 스킬] 시전 시, 모든 방어력을 잃고 해당 수치를 캐릭터 공격력으로 전환",
    ContentTC = "釋放[終結技]時，失去全部防禦，轉化為角色攻擊。",
    TextMapContent = "释放[终结技]时，失去全部防御，转化为角色攻击。",
    TextMapId = "RLBlessing_SimpleDesc_713"
  },
  RLBlessing_SimpleDesc_714 = {
    ContentEN = "Ignores the target's DEF by a certain amount when dealing Skill DMG. The effect intensifies at lower HP.",
    ContentFR = "Les Dégâts de compétence ignorent une partie de la DÉF de la cible, effet renforcé lorsque les PV sont faibles.",
    ContentJP = "スキルダメージが目標の防御力を一部無視する。HP割合が低い場合はその効果がさらに強くなる。",
    ContentKR = "스킬 대미지가 대상의 일정 방어를 무시, HP 비율이 낮을 시 효과 상승",
    ContentTC = "技能傷害無視目標一定防禦，生命百分比較低時效果更強。",
    TextMapContent = "技能伤害无视目标一定防御，生命百分比较低时效果更强。",
    TextMapId = "RLBlessing_SimpleDesc_714"
  },
  RLBlessing_SimpleDesc_715 = {
