  RLTreasureGroup_Desc_101 = {
    ContentEN = "With all <Highlight>2</> [Guardian Knight] Artefacts collected, your character gains Ultra Shield points equal to <Highlight>10%</> Max HP every <Highlight>10</>s while within [Abyssoids].",
    ContentFR = "Une fois les <Highlight>2</> Artéfacts de [Chevalier gardien] réunis, gagne des points d’Ultra-bouclier équivalents à <Highlight>10 %</> des PV max toutes les <Highlight>10</> s dans les [Umbrés], jusqu’à quitter les [Umbrés].",
    ContentJP = "「護衛騎士」のレリック全<Highlight>2</>個を集めると、「暗影」で<Highlight>10</>秒ごとに自身の最大HP<Highlight>10%</>に相当する過負荷シールドを獲得する（「暗影」通過まで持続）。",
    ContentKR = "[호위 기사]의 모든 유물 <Highlight>2</>개를 수집한 후, [그림자]에서 <Highlight>10</>초마다 자신 최대 HP의 <Highlight>10%</>에 해당하는 오버로드 실드를 획득한다. [그림자]를 통과할 때까지 지속된다.",
    ContentTC = "收集[護衛騎士]的全部<Highlight>2</>件遺物後，[幽影]中每<Highlight>10</>秒獲得自身最大生命<Highlight>10%</>的超限護盾直到通過[幽影]。",
    TextMapContent = "收集[护卫骑士]的全部<Highlight>2</>件遗物后，[幽影]中每<Highlight>10</>秒获得自身最大生命<Highlight>10%</>的超限护盾直到通过[幽影]。",
    TextMapId = "RLTreasureGroup_Desc_101"
  },
  RLTreasureGroup_Desc_102 = {
    ContentEN = [[
With all <Highlight>3</> [Covenant of the God of Abundance] Artefacts collected, your character gains <Highlight>10%</> DMG Increase for every <Highlight>100</> Embers held.
 If Embers are below <Highlight>200</>, reduces Damage Taken by <Highlight>30%</>.]],
    ContentFR = "Une fois les <Highlight>3</> Artéfacts de [Pacte du Dieu de la Prospérité] réunis, les dégâts infligés augmentent de <Highlight>10 %</> tous les <Highlight>100</> Braises possédées.\nSi les Braises sont inférieures à <Highlight>200</>, les dégâts subis sont réduits de <Highlight>30 %</>.",
    ContentJP = "「繁栄の神の契約」のレリック全<Highlight>3</>個を集めると、所持するエンバー<Highlight>100</>ごとにダメージ<Highlight>10%</>アップ。\n エンバーが<Highlight>200</>未満のとき、被ダメージ<Highlight>30%</>軽減。",
    ContentKR = "[번영의 신의 계약]의 모든 유물 <Highlight>3</>개를 수집한 후, <Highlight>100</> 잿불을 보유할 때마다 대미지가 <Highlight>10%</> 상승한다.\n잿불이 <Highlight>200</> 이하일 시, 받는 대미지가 <Highlight>30%</> 감소한다.",
    ContentTC = "收集[繁榮之神的契約]的全部<Highlight>3</>件遺物後，每擁有<Highlight>100</>余燼傷害提高<Highlight>10%</>。\n若余燼少於<Highlight>200</>，受到傷害降低<Highlight>30%</>。",
    TextMapContent = "收集[繁荣之神的契约]的全部<Highlight>3</>件遗物后，每拥有<Highlight>100</>余烬伤害提高<Highlight>10%</>。\n若余烬少于<Highlight>200</>，受到伤害降低<Highlight>30%</>。",
    TextMapId = "RLTreasureGroup_Desc_102"
  },
  RLTreasureGroup_Desc_103 = {
    ContentEN = "With all <Highlight>4</> [Four Elemental Seals] Artefacts collected, sets Trigger Probability to <Highlight>50%</> and Damage Multiplier to <Highlight>100%</>, and converts all damage to True Damage.",
    ContentFR = "Une fois les <Highlight>4</> Artéfacts de [Sceau des Quatre Éléments] réunis, la Chance de déclenchement est fixée à <Highlight>50 %</>, le Multiplicateur de dégâts à <Highlight>100 %</>, et tous les dégâts sont convertis en Dégâts purs.",
    ContentJP = "「四象の銘印」のレリック全<Highlight>4</>個を集めると、発動確率が<Highlight>50%</>に上昇、ダメージ倍率が<Highlight>100%</>に上昇、さらにダメージが固定ダメージになる。",
    ContentKR = "[사상명인]의 모든 유물 <Highlight>4</>개를 수집한 후, 발동 확률이 <Highlight>50%</>까지, 대미지 배율이 <Highlight>100%</>까지 상승하고 입히는 대미지가 고정 대미지로 변경된다.",
    ContentTC = "收集[四象銘印]的全部<Highlight>4</>件遺物後，觸發概率提高至<Highlight>50%</>，傷害倍率提高至<Highlight>100%</>，且造成傷害變為真實傷害。",
    TextMapContent = "收集[四象铭印]的全部<Highlight>4</>件遗物后，触发概率提高至<Highlight>50%</>，伤害倍率提高至<Highlight>100%</>，且造成伤害变为真实伤害。",
    TextMapId = "RLTreasureGroup_Desc_103"
  },
  RLTreasureGroup_Desc_104 = {
    ContentEN = "With all <Highlight>4</> [Penitent Knight] Artefacts collected, removes the penalty and increases total damage bonus to <Highlight>400%</>.",
    ContentFR = "Une fois les <Highlight>4</> Artéfacts de [Chevalier pénitent] réunis, la contrepartie est annulée, et le bonus total de dégâts passe à <Highlight>400 %</>.",
    ContentJP = "「贖罪の騎士」のレリック全<Highlight>4</>個を集めると代償不要になり、与ダメージ合計が<Highlight>400%</>に上昇。",
    ContentKR = "[속죄하는 기사]의 모든 유물 <Highlight>4</>개를 수집한 후, 더 이상 대가를 치르지 않으며, 총 상승하는 대미지가 <Highlight>400%</>로 변경된다.",
    ContentTC = "收集[贖罪騎士]的全部<Highlight>4</>件遺物後不再需要代價，且總共提高傷害變為<Highlight>400%</>。",
    TextMapContent = "收集[赎罪骑士]的全部<Highlight>4</>件遗物后不再需要代价，且总共提高伤害变为<Highlight>400%</>。",
    TextMapId = "RLTreasureGroup_Desc_104"
  },
  RLTreasureGroup_Desc_105 = {
    ContentEN = "With all <Highlight>2</> [Forlorn Sorceress] Artefacts collected, increases [Stance] reduction by <Highlight>100%</>, and damage dealt to enemies under [Ask's Retribution] by <Highlight>100%</>.",
    ContentFR = "Une fois les <Highlight>2</> Artéfacts de [Sorcière éplorée] réunis, l’affaiblissement de la posture augmente de <Highlight>100 %</>, et les dégâts infligés aux ennemis sous [Châtiment d’Ask] augmentent de <Highlight>100 %</>.",
    ContentJP = "「幽惘の術士」のレリック全<Highlight>2</>個を集めると、「体勢」削り効率<Highlight>100%</>上昇、敵が「アスクパニッシュ」状態に入ると与ダメージ<Highlight>100%</>上昇。",
    ContentKR = "[유망술사]의 모든 유물 <Highlight>2</>개를 수집한 후, [전투 태세]의 약화 효율이 <Highlight>100%</> 상승하고, 적이 [아스크의 징벌] 진입 후 대미지가 <Highlight>100%</> 상승한다.",
    ContentTC = "收集[幽惘術士]的全部<Highlight>2</>件遺物後，[戰姿]削減效率提高<Highlight>100%</>，敵人進入[埃斯刻懲戒]後傷害提高<Highlight>100%</>。",
    TextMapContent = "收集[幽惘术士]的全部<Highlight>2</>件遗物后，[战姿]削减效率提高<Highlight>100%</>，敌人进入[埃斯刻惩戒]后伤害提高<Highlight>100%</>。",
    TextMapId = "RLTreasureGroup_Desc_105"
  },
