  RLTreasure_Desc_Unknown = {
    ContentEN = "This Artefact remains shrouded in mist",
    ContentFR = "Cet artéfact demeure encore voilé par la brume.",
    ContentJP = "このレリックはまだ霧の中にある。",
    ContentKR = "이 유물은 아직 안개 속에 있습니다.",
