  RegionReputation_EntrustContent_huaxv_05 = {
    ContentEN = "Mrrrow, meow meow. Meow meow meow... (It seems to be saying, \"Give me stuff!\")",
    ContentFR = "Mrrr miaou, miaou miaou miaou, mrrr... (On dirait qu’il dit : donnez-moi quelque chose !)",
    ContentJP = "ミミニャーニャー、ニャーニャーニャー、ミミ……（品物をよこせ、と言っているようだ！）",
    ContentKR = "야옹, 야옹, 야오오옹... (뭔가를 내놓으라는 뜻인 것 같다!)",
