    ContentFR = "Mer de Poussière",
    ContentJP = "塵砂の荒海",
    ContentKR = "낙진의 바다",
    ContentTC = "塵漠石海",
    TextMapContent = "尘漠石海",
    TextMapId = "StoryDungeon03_Title"
