  TERMEXP_3202_Skill01 = {
    ContentEN = "Increases Skill Speed and [Sommelier's Blades] Launch Speed. While [Tipsy] is active, the duration timer of [Sommelier's Blades] is paused, and Camilla gains immunity to Hitstun.",
