  TERMEXP_Rou_10104_GlowingTree = {
    ContentEN = "Heals nearby allies within <Highlight>10</>m for <Highlight>5%</> of their Max HP per second. Lasts <Highlight>10</>s. Only 1 may be active on the battlefield at a time.",
    ContentFR = "Soigne chaque seconde les alliés dans un rayon de <Highlight>10</> m à hauteur de <Highlight>5 %</> de leurs PV max. Dure <Highlight>10</> s.\nUn seul arbre peut exister à la fois.",
    ContentJP = "1秒ごとに周囲<Highlight>10</>メートル範囲内の味方全員に対し、各々の最大HPの<Highlight>5%</>に相当する回復効果を与える。持続時間は<Highlight>10</>秒、同時に1つしか存在しない。",
    ContentKR = "매초 주변 <Highlight>10</>m 범위 내의 다른 팀원에게 최대 HP <Highlight>5%</>에 해당하는 치료를 제공한다. 지속 시간 <Highlight>10</>초, 동시에 1개 존재할 수 있다.",
    ContentTC = "每秒為周圍<Highlight>10</>米範圍內的其他隊友提供其最大生命<Highlight>5%</>的治療。持續時間<Highlight>10</>秒，同時最多存在1個。",
    TextMapContent = "每秒为周围<Highlight>10</>米范围内的其他队友提供其最大生命<Highlight>5%</>的治疗。持续时间<Highlight>10</>秒，同时最多存在1个。",
    TextMapId = "TERMEXP_Rou_10104_GlowingTree"
  },
  TERMEXP_Rou_10104_Lumileaf = {
