  UIGuide_Hyper_1 = {
    ContentEN = "<H>Calamity Weapons</> have unique upgrade paths and Potential effects. Increasing a weapon's <H>Calamity Smelting Level</> unlocks Potentials at that level.",
    ContentFR = "Les <H>Armes de calamité</> possèdent une voie d’évolution et des effets de potentiel uniques. Augmenter le <H>niveau de fusion de calamité</> permet de débloquer les potentiels correspondants.",
    ContentJP = "<H>カラミティアームズ</>には独自の成長ルートと潜在能力があります。カラミティアームズの<H>災厄製錬レベル</>を上げると、そのレベルの潜在能力を解放できます",
    ContentKR = "<H>재앙 무기</>는 고유한 성장 루트와 잠재력 효과를 지닙니다. 재앙 무기의 <H>재앙 용해 레벨</>을 올리면 해당 레벨의 잠재력 효과를 해제할 수 있습니다.",
    ContentTC = "<H>災厄武器</>具有獨特的成長路線與潛能效果。提升災厄武器的<H>災厄熔煉等級</>，可以解鎖該等級下的潛能",
    TextMapContent = "<H>灾厄武器</>具有独特的成长路线与潜能效果。提升灾厄武器的<H>灾厄熔炼等级</>，可以解锁该等级下的潜能",
    TextMapId = "UIGuide_Hyper_1"
  },
  UIGuide_Hyper_2 = {
    ContentEN = "Completing Calamity Furnace Level Tasks increases your <H>Calamity Furnace Level</>, which raises the <H>Smelting Level Cap</> for all Calamity Weapons.",
    ContentFR = "Accomplir les missions du fourneau et augmenter le <H>niveau du Fourneau de calamité</> permet d’augmenter la <H>limite de niveau de fusion</> de toutes les armes de calamité.",
    ContentJP = "災厄の炉レベルクエストを達成し、<H>災厄の炉レベル</>を上げると、すべてのカラミティアームズの<H>製錬レベル上限</>を上げられます",
    ContentKR = "재앙의 용광로 레벨 퀘스트를 완료하고 <H>재앙의 용광로 레벨</>을 올리면, 모든 재앙 무기의 <H>용해 최고 레벨</>이 증가합니다.",
    ContentTC = "完成災厄熔爐等級任務，提升<H>災厄熔爐等級</>，可以提升全部災厄武器的<H>熔煉等級上限</>",
