  UIGuide_TongLv_1 = {
    ContentEN = "Some characters possess unique Consonance Weapons. These weapons level up with the character and cannot be replaced or upgraded separately, but can be fitted with Demon Wedges.",
    ContentFR = "Certains personnages possèdent une Arme de Consonance unique. Celle-ci évolue avec le niveau du personnage et ne peut être remplacée ni améliorée indépendamment, mais elle peut être équipée de Sceaux démoniaques.",
    ContentJP = "一部のキャラクターは、固有の同調武器を持っている。同調武器はキャラクターのレベルに応じて自動的に成長し、武器の変更や個別育成は行えないが、魔の楔を装着することはできる。",
    ContentKR = "일부 캐릭터는 고유의 동조 무기를 가지고 있습니다. 동조 무기는 캐릭터 레벨 상승에 따라 함께 레벨업되며, 교체하거나 별도로 육성할 수 없으나, 악마의 쐐기를 장착할 수 있습니다.",
    ContentTC = "部分角色擁有獨特的同律武器。同律武器會隨著角色等級提升而升級，無法替換與單獨培養，但可以裝配魔之楔。",
    TextMapContent = "部分角色拥有独特的同律武器。同律武器会随着角色等级提升而升级，无法替换与单独培养，但可以装配魔之楔。",
    TextMapId = "UIGuide_TongLv_1"
  },
  UIGuide_TrainingGround_1 = {
    ContentEN = "Sandrealm Meditation lets you revisit and battle past enemies in a controlled environment, helping you familiarise yourself with their moves and hone your combat skills.",
    ContentFR = "La Méditation du Royaume des Sables vous permet d’affronter librement des ennemis déjà rencontrés, afin d’étudier leurs attaques et perfectionner vos compétences.",
    ContentJP = "「砂海の瞑想」では、過去に戦った敵と回想のなかで戦うことができます。敵の戦い方を学んで、自分の腕前を上げましょう。",
    ContentKR = "모래 바다의 명상에서는 이전에 만났던 적들을 회상하며 자유롭게 전투할 수 있습니다. 이를 통해 적의 공격 패턴을 익히고 자신의 스킬을 테스트할 수 있습니다.",
    ContentTC = "在沙海冥想中，可以回憶曾經見過的敵人，並與它們進行自主的戰鬥。可以以此熟悉它們的招式、測試自己的技能。",
    TextMapContent = "在沙海冥想中，可以回忆曾经见过的敌人，并与它们进行自主的战斗。可以以此熟悉它们的招式、测试自己的技能。",
    TextMapId = "UIGuide_TrainingGround_1"
  },
  UIGuide_TrainingGround_2 = {
    ContentEN = "Within the <H>Gritty Vortex</> in Sandrealm Meditation, you'll find combat supplies such as <H>Ammo Supply Chests</>, <H>Sal Volatile</>, and <H>Cognizing Sal Volatile</> to facilitate your combat.",
    ContentFR = "Dans le <H>Tourbillon de sable</>, vous trouverez des <H>Caisses de munitions</>, du <H>Sel volatil</>, du <H>Sel volatil concentré</> et d’autres fournitures de combat pour faciliter vos entraînements.",
    ContentJP = "「砂海の瞑想」の<H>砂海の渦</>では、<H>弾薬補給箱</>、<H>気つけ薬</>、<H>興奮剤</>などの戦闘が便利になるアイテムがドロップします。",
    ContentKR = "모래 바다의 명상 속 <H>모래 바다 소용돌이</>에는 <H>탄약 보급 상자</>, <H>스멜링 솔트</>, <H>정신 집중 스멜링 솔트</> 등 전투 보급품이 등장하여 더 효과적인 전투 테스트가 가능합니다.",
    ContentTC = "在沙海冥想的<H>沙海漩渦</>中，會出現<H>彈藥補給箱</>、<H>嗅鹽</>、<H>凝神嗅鹽</>等戰鬥補給，便於更好地進行戰鬥測試。",
    TextMapContent = "在沙海冥想的<H>沙海漩涡</>中，会出现<H>弹药补给箱</>、<H>嗅盐</>、<H>凝神嗅盐</>等战斗补给，便于更好地进行战斗测试。",
    TextMapId = "UIGuide_TrainingGround_2"
  },
