  UI_Accessory_Desc_10001 = {
    ContentEN = "The protagonist of the well-known fairy tale \"JoeJoe's Bizarre Adventure\" across the Atlasia Continent. This chickie named JoeJoe awakens in new places each day, befriends interesting characters, and embarks on bizarre quests to discover the meaning of life and thwart villainous plots.",
    ContentFR = "Héros du célèbre conte « <I>L’Étrange Aventure de Pioupiou</> », répandu sur tout le continent d’Atlasia. Chaque jour, le petit poussin s’éveille dans un lieu différent, rencontre de nouveaux compagnons et s’élance dans une odyssée singulière pour découvrir le sens de sa vie — et déjouer les complots des méchants.",
    ContentJP = "アトラシア大陸で親しまれている童話『ひょこちゃんの奇妙な冒険』の主人公。\n 毎日異なる場所で目覚め、新たな友人と出会い、人生の意味を追い求めるひょこちゃんが、奇妙な冒険を繰り広げ、悪者の陰謀を暴くストーリーとなっている。",
    ContentKR = "아트라시아 대륙에서 유명한 동화 이야기 〈삐약이의 놀라운 모험〉의 주인공이자 삐약이라고 불리는 병아리. 매일 다른 곳에서 깨어난 삐약이가 다양한 친구들을 사귀고 놀라운 모험을 떠나 계생의 의미를 찾고, 악당의 음모를 파헤치는 이야기를 담고 있다.",
    ContentTC = "阿特拉西亞大陸知名童話故事《啾啾的奇妙冒險》中的主角——一只名叫啾啾的小雞，講述啾啾每天在不同的位置蘇醒，結識不同的友人，踏上奇妙冒險尋找雞生意義，揭開反派陰謀的故事。",
    TextMapContent = "阿特拉西亚大陆知名童话故事《啾啾的奇妙冒险》中的主角——一只名叫啾啾的小鸡，讲述啾啾每天在不同的位置苏醒，结识不同的友人，踏上奇妙冒险寻找鸡生意义，揭开反派阴谋的故事。",
    TextMapId = "UI_Accessory_Desc_10001"
  },
  UI_Accessory_Desc_10002 = {
    ContentEN = "WARNING: NON-EDIBLE!",
    ContentFR = "À ne surtout pas consommer !",
    ContentJP = "食べられません！",
    ContentKR = "주의, 먹지 말 것!",
    ContentTC = "切記，不可食用！",
    TextMapContent = "切记，不可食用！",
    TextMapId = "UI_Accessory_Desc_10002"
  },
  UI_Accessory_Desc_10003 = {
    ContentEN = "Vivacious, adorable, lively, beautiful... No words in the world do justice to the magical allure of these feline ears.",
    ContentFR = "Vif, adorable, espiègle, splendide... Tous les mots manquent pour capturer l’irrésistible magie de ces oreilles félines.",
    ContentJP = "しなやかで、明るくキュートで、美しい……世の中のすべての萌えが色あせて見える。これこそ、猫耳の持つ抗えない魔力。",
    ContentKR = "귀엽다, 깜찍하다, 발랄하다, 아름답다... 세간의 온갖 미사여구도 고양이 귀 앞에서는 빛을 잃는다. 이게 바로 고양이 귀가 가진 거부할 수 없는 매력!",
    ContentTC = "靈動、可愛、活潑、美麗……世上一切對美好的形容詞在貓耳的面前都會顯得黯淡無光，這就是貓耳那讓人無法拒絕的魔力。",
    TextMapContent = "灵动、可爱、活泼、美丽……世上一切对美好的形容词在猫耳的面前都会显得黯淡无光，这就是猫耳那让人无法拒绝的魔力。",
    TextMapId = "UI_Accessory_Desc_10003"
  },
  UI_Accessory_Desc_10004 = {
    ContentEN = "Filled with the boundless inspiration and fervour of Lunosmith, this portable Cinder always reminds you of the vibrant forge flames fanned by it.",
    ContentFR = "Infusé de l’inspiration et de la fougue de Luno, la forgeronne, ce Cinder portatif évoque sans cesse la fournaise ardente qu’il attise de ses battements.",
    ContentJP = "携帯版「すみっコ」。ルーナ族の鍛冶師の情熱とインスピレーションが込められており、どこにいても金床の灼熱を思い出させてくれる。",
    ContentKR = "휴대용 까망이. 대장장이 루나의 영감과 열정이 가득 담겨 있어 까망이가 끊임없이 내뿜는 화롯불을 연상시킨다.",
    ContentTC = "烏烏隨身攜帶款，灌注著鐵匠皎皎飽滿的靈感和熱情，讓人隨時隨地想起那由烏烏不斷鼓動的熱烈爐火。",
    TextMapContent = "乌乌随身携带款，灌注着铁匠皎皎饱满的灵感和热情，让人随时随地想起那由乌乌不断鼓动的热烈炉火。",
    TextMapId = "UI_Accessory_Desc_10004"
  },
  UI_Accessory_Desc_10005 = {
    ContentEN = "An emblem of elegance, the embodiment of grace — or perhaps, just a butterfly unable to flutter its wings.",
    ContentFR = "Symbole de noblesse, incarnation des bonnes manières... ou peut-être simplement un papillon incapable de s’envoler.",
    ContentJP = "端正の象徴、礼儀の具現、あるいは、飛べない蝶。",
    ContentKR = "단정함의 상징, 예의의 구현, 혹은 날지 못하는 나비 한 마리.",
    ContentTC = "端莊的象征，禮儀的具現，亦或是，一只無法飛翔的蝴蝶。",
    TextMapContent = "端庄的象征，礼仪的具现，亦或是，一只无法飞翔的蝴蝶。",
    TextMapId = "UI_Accessory_Desc_10005"
  },
  UI_Accessory_Desc_10006 = {
    ContentEN = "In every era, dragons have captivated hearts and stirred imaginations — powerful, untamed, and ever elusive. Their rarity only deepens the mystery, making them the perfect canvas for boundless fantasy.",
    ContentFR = "Les dragons fascinent chaque époque. Puissants, sauvages, insaisissables — leur rareté les drape d’une aura de mystère. C’est cette brume d’imaginaire qui nourrit la créativité des peuples depuis toujours.",
    ContentJP = "ドラゴンはいつの時代も人々を惹きつけてやまない存在だ。強大な大自然の申し子だが、目撃者はほとんどいないため具体的な姿形はベールに包まれている。その曖昧なイメージこそが自由な空想の土壌となっている。",
    ContentKR = "용은 시대를 초월하여 사람들에게 사랑받는 존재다. 강력하고 야성적이지만, 동시에 거의 볼 수 없기에 더욱 몽환적이고 매력적이며, 모두에게 마음껏 상상할 공간을 제공한다.",
    ContentTC = "龍在任何時代都擁有萬千擁躉，它強大、野性卻又因鮮有人見而顯得疏遠朦朧。正是這朦朧的概念，為人們搭建起肆意揮灑想像的無垠熱土。",
    TextMapContent = "龙在任何时代都拥有万千拥趸，它强大、野性却又因鲜有人见而显得疏远朦胧。正是这朦胧的概念，为人们搭建起肆意挥洒想象的无垠热土。",
    TextMapId = "UI_Accessory_Desc_10006"
  },
  UI_Accessory_Desc_10007 = {
