  UI_Accessory_Desc_13005 = {
    ContentEN = "Woven from the night's shadow, it gathers the world's rain and haze, folding them into a hush.",
    ContentFR = "Tissé dans l’ombre de la nuit, il recueille brumes et pluies du monde, puis les replie dans le silence.",
    ContentJP = "夜色をお面として、江湖の煙雨をすべて収める。",
    ContentKR = "밤빛으로 얼굴을 가리고, 강호의 안개비를 거두어들인다.",
    ContentTC = "以夜色為面，斂盡江湖煙雨。",
    TextMapContent = "以夜色为面，敛尽江湖烟雨。",
    TextMapId = "UI_Accessory_Desc_13005"
  },
  UI_Accessory_Desc_13009 = {
    ContentEN = "Vivacious, adorable, lively, beautiful... No words in the world can do justice to the irresistible allure of a feline tail.",
    ContentFR = "Vif, adorable, espiègle, splendide... Tous les mots du monde pâlissent face à l’irrésistible magie de cette queue féline.",
    ContentJP = "しなやかで、かわいくて、元気で、美しい……この世の「美しい」を形容する言葉は、猫のしっぽの前では色褪せてしまう。それが猫のしっぽの、抗えない魔力。",
    ContentKR = "귀엽다, 깜찍하다, 발랄하다, 아름답다... 세간의 온갖 미사여구도 고양이 꼬리 앞에서는 빛을 잃는다. 그것이 바로 고양이 꼬리가 가진 거부할 수 없는 매력이다.",
    ContentTC = "靈動、可愛、活潑、美麗……世上一切對美好的形容詞在貓尾巴的面前都會顯得黯淡無光，這就是貓尾巴那讓人無法拒絕的魔力。",
    TextMapContent = "灵动、可爱、活泼、美丽……世上一切对美好的形容词在猫尾巴的面前都会显得黯淡无光，这就是猫尾巴那让人无法拒绝的魔力。",
    TextMapId = "UI_Accessory_Desc_13009"
  },
  UI_Accessory_Desc_13053 = {
    ContentEN = "Let all things burn, until nothing remains.",
    ContentFR = "Tout réduire en cendres, puis retourner au néant.",
    ContentJP = "すべてを焼き尽くせ。何一つ残らぬまで。",
    ContentKR = "모든 것을 불태워, 허무로 돌아가리라.",
    ContentTC = "燒燼一切，回歸虛無。",
    TextMapContent = "烧烬一切，回归虚无。",
    TextMapId = "UI_Accessory_Desc_13053"
  },
  UI_Accessory_Desc_13057 = {
    ContentEN = "Listen to the ticking of the clockwork.",
    ContentFR = "Écouter l’écho du remontoir.",
    ContentJP = "耳を澄ませ。絡繰りが刻む時の音に。",
    ContentKR = "태엽의 울림에 귀 기울여라.",
    ContentTC = "聆聽發條的迴響。",
    TextMapContent = "聆听发条的回响。",
    TextMapId = "UI_Accessory_Desc_13057"
  },
  UI_Accessory_Desc_20001 = {
    ContentEN = "Wisdom precisely encircled in those round frames, greatly magnifying the wearer's aura of sagacity.",
    ContentFR = "La sagesse s’inscrit dans le cercle parfait de ces montures, amplifiant l’aura clairvoyante de celle ou celui qui les porte.",
    ContentJP = "着用者の知性を無限に引き出すメガネ。知性を引き立てる円形のガラスが精密なフレームにはまっている。",
    ContentKR = "지성미를 풍기는 동그란 안경, 착용자의 스마트함을 더 돋보이게 한다.",
    ContentTC = "智慧的圓嵌進精準的框，無限放大著佩戴者睿智的氣息。",
    TextMapContent = "智慧的圆嵌进精准的框，无限放大着佩戴者睿智的气息。",
    TextMapId = "UI_Accessory_Desc_20001"
  },
  UI_Accessory_Desc_20002 = {
    ContentEN = "Eyes are but obstacles to truly observing and perceiving the world.",
    ContentFR = "Les yeux ne sont que des voiles qui entravent notre capacité à ressentir véritablement le monde.",
    ContentJP = "両眼は、この世界を心で感じ、理解する妨げにすぎない。",
    ContentKR = "두 눈은 우리가 마음으로 세상을 관측하고 느끼는 데 방해가 될 뿐이다.",
    ContentTC = "雙眼只是妨礙吾等用心去觀測、去感受世界的阻礙。",
    TextMapContent = "双眼只是妨碍吾等用心去观测、去感受世界的阻碍。",
    TextMapId = "UI_Accessory_Desc_20002"
  },
  UI_Accessory_Desc_20003 = {
    ContentEN = "A butterfly that waltzes through tempests, providing a silent vigil for those unsettled by the roar of thunder, until the storm quiets and the fear subsides.",
    ContentFR = "Un papillon qui danse dans l’orage, veillant silencieusement sur ceux que la foudre effraie, jusqu’à ce que le tonnerre se taise et que la peur se dissipe.",
    ContentJP = "雷雨の夜に舞う蝶。雷鳴に怯える人々に寄りそい、嵐が過ぎ去り、不安が消えるまでそばにいてくれる。",
    ContentKR = "뇌우가 치는 밤에 춤추는 나비는 천둥소리를 두려워하는 이들 곁을 조용히 지켜준다. 천둥이 그치고, 두려움이 사라질 때까지.",
    ContentTC = "在雷雨夜飛舞的蝴蝶，安靜地陪伴在每個畏懼雷鳴之人的身旁，直至雷聲消散，直至恐慌褪去。",
    TextMapContent = "在雷雨夜飞舞的蝴蝶，安静地陪伴在每个畏惧雷鸣之人的身旁，直至雷声消散，直至恐慌褪去。",
    TextMapId = "UI_Accessory_Desc_20003"
  },
  UI_Accessory_Desc_20004 = {
    ContentEN = "According to the lore of certain Charon tribes, this ethereal butterfly emerges each day from the white blossoms of Mother Embla, only to fade into the dusky mists of Father Ask.",
    ContentFR = "Chez certains clans Charon, on raconte que ces papillons naissent chaque jour des fleurs blanches de la Mère Embla, avant de se dissoudre dans les brumes crépusculaires du Père Ask.",
    ContentJP = "カロン族の伝説によると、毎日、母なる神エムブラの白い花から蝶が生まれ、そして父なる神アスクの暗い霧へと消えていく。",
    ContentKR = "일부 카론 부족 전설에 따르면, 안개 나비는 어머니 신 엠블라의 하얀 꽃밭에서 태어나, 아버지 신 아스크의 어두운 안갯속에서 사라진다고 한다.",
    ContentTC = "在部分卡戎部族的傳說中，霧蝶每一日誕生自母神茵布拉的白色花叢之間，消逝在父神埃斯刻的昏暗薄霧左右。",
    TextMapContent = "在部分卡戎部族的传说中，雾蝶每一日诞生自母神茵布拉的白色花丛之间，消逝在父神埃斯刻的昏暗薄雾左右。",
    TextMapId = "UI_Accessory_Desc_20004"
  },
  UI_Accessory_Desc_20005 = {
    ContentEN = "A swift solution for sudden discomfort.",
    ContentFR = "Quand la douleur frappe, appliquez-le sans attendre.",
    ContentJP = "ケガしたらとりあえず巻いておこう。",
    ContentKR = "아프면 붙이세요.",
    ContentTC = "痛，就貼。",
    TextMapContent = "痛，就贴。",
    TextMapId = "UI_Accessory_Desc_20005"
  },
  UI_Accessory_Desc_20006 = {
    ContentEN = "Poisonous fog, fire, smoke, sand and dust... This simple structure interprets that sustaining the possibility of survival is never easy.",
    ContentFR = "Brouillards toxiques, flammes, fumée, sable... Derrière cette structure en apparence rudimentaire se cache tout ce qui, bien souvent, sépare la survie de la mort.",
    ContentJP = "毒ガス、炎、煙……単純な構造ながら、生存という決して単純ではない可能性を維持している。",
    ContentKR = "독안개, 강렬한 불길, 화약연기, 모래먼지의 간단한 구조이지만 생명 유지의 절대 간단하지 않은 가능성을 유지하고 있다.",
    ContentTC = "毒霧、烈火、硝煙、沙塵，簡單的結構，維繫著生命存續絕不簡單的可能。",
    TextMapContent = "毒雾、烈火、硝烟、沙尘，简单的结构，维系着生命存续绝不简单的可能。",
    TextMapId = "UI_Accessory_Desc_20006"
  },
  UI_Accessory_Desc_20007 = {
    ContentEN = "Yearnings for the sky could not transcend earthly bounds. The outstretched wings speak volumes of the longing for freedom.",
    ContentFR = "Le désir de voler s’enracine dans la cage de chair, et ces ailes entrouvertes murmurent le rêve de liberté.",
    ContentJP = "飛翔への渇望は肉体という牢獄に根付き、その広げた翼は自由への憧れを表している。",
    ContentKR = "비행을 향한 갈망은 육체라는 새장에 뿌리를 내린 채, 자유를 동경하며 날개를 쭉 펼치고 있다.",
    ContentTC = "飛翔的渴望紮根於肉體的囚籠，那伸展的羽翼，便是對自由的向往。",
    TextMapContent = "飞翔的渴望扎根于肉体的囚笼，那伸展的羽翼，便是对自由的向往。",
    TextMapId = "UI_Accessory_Desc_20007"
  },
  UI_Accessory_Desc_20008 = {
    ContentEN = "Always keeps the audience wondering whether the next moment will reveal a dove or a rose.",
    ContentFR = "L’on ne saura jamais si, au prochain battement de paupières, apparaîtra une colombe... ou une rose.",
    ContentJP = "瞬きの後に見えるのがハトかバラか、誰にも知らないことだ。",
    ContentKR = "눈을 감았다 뜨면 보이는 게 비둘기일지, 장미일지 누구도 예상할 수 없다.",
    ContentTC = "人們永遠無法知道眨眼之後看到的會是一只鴿子還是一朵玫瑰。",
    TextMapContent = "人们永远无法知道眨眼之后看到的会是一只鸽子还是一朵玫瑰。",
    TextMapId = "UI_Accessory_Desc_20008"
  },
  UI_Accessory_Desc_20010 = {
    ContentEN = "This fake moustache lends its wearer an air of gravitas and wisdom, though it demands occasional adjustments to ensure it stays firmly in place.",
    ContentFR = "Une fausse moustache conférant à celle qui la porte une prestance tranquille. Il suffit toutefois de la presser deux fois de temps à autre, afin d’éviter qu’elle ne se détache.",
    ContentJP = "この付けヒゲを着けると落ち着いた大人びた印象に。ときどきポンポンと押さえて、落ちないように気をつけよう。",
    ContentKR = "어른스럽고 중후한 느낌을 주는 가짜 수염. 떨어지지 않도록 주기적으로 손으로 두어 번 눌러 줘야 한다.",
    ContentTC = "能讓佩戴者顯得老成穩重的假胡子，每過一段時間記得要用手按壓兩次，以防胡子脫落哦。",
    TextMapContent = "能让佩戴者显得老成稳重的假胡子，每过一段时间记得要用手按压两次，以防胡子脱落哦。",
    TextMapId = "UI_Accessory_Desc_20010"
  },
  UI_Accessory_Desc_20011 = {
    ContentEN = "Broaden your perspective and see the world unfold before your eyes.",
    ContentFR = "Ouvrez votre regard... et laissez le monde se dévoiler.",
    ContentJP = "視野を広げ、世界を見渡そう。",
    ContentKR = "넓은 시야로 세상을 바라보라.",
    ContentTC = "打開眼界，放眼世界。",
    TextMapContent = "打开眼界，放眼世界。",
    TextMapId = "UI_Accessory_Desc_20011"
  },
  UI_Accessory_Desc_20026 = {
    ContentEN = "Though the past cannot be relived, let neither your dreams nor the traces of your existence fade into silence.",
    ContentFR = "Même si le passé s’est effacé, n’oubliez jamais le rêve qui vous porte... ni la trace qu’une vie laisse derrière elle.",
    ContentJP = "たとえ過ぎ去った日々でも、生きる者としての夢と証をどうか忘れないで。",
    ContentKR = "비록 과거는 사라졌지만, 인간으로서의 꿈과 증명을 잊지 말아주세요.",
    ContentTC = "縱使過去已逝，也請不要忘記生而為人的夢想與證明。",
    TextMapContent = "纵使过去已逝，也请不要忘记生而为人的梦想与证明。",
    TextMapId = "UI_Accessory_Desc_20026"
  },
  UI_Accessory_Desc_20027 = {
    ContentEN = "A crimson charm sways beside the monocle, catching the breeze — as if some scholar, somewhere, just flipped a page and murmured, \"...hm.\"",
    ContentFR = "Quand le pendentif rouge frissonne dans le vent, on croirait entendre un chercheur tourner une page et murmurer : « ... hmm. »",
    ContentJP = "夜風が赤いペンダントを揺らすと、どこかで本をめくる音が聞こえた気がした。",
    ContentKR = "안경알 옆의 주홍색 펜던트 위로 밤바람이 불면, 어떤 학자가 책을 넘기는 바스락거리는 소리가 들려온다.",
    ContentTC = "當夜風吹過鏡片旁的緋色吊墜時，彷彿能聽到某位學者沙沙的翻書聲。",
    TextMapContent = "当夜风吹过镜片旁的绯色吊坠时，仿佛能听到某位学者沙沙的翻书声。",
    TextMapId = "UI_Accessory_Desc_20027"
  },
  UI_Accessory_Desc_20028 = {
    ContentEN = "Bubbly, bright, and impossible to ignore.",
    ContentFR = "Vibrant, joyeux... impossible à ignorer.",
    ContentJP = "にぎやかでハッピーな雰囲気、悪くないだろう？",
    ContentKR = "상쾌하고 활기찬 공기를 느껴라.",
    ContentTC = "感受這鮮活的、快活的空氣。",
    TextMapContent = "感受这鲜活的、快活的空气。",
    TextMapId = "UI_Accessory_Desc_20028"
  },
  UI_Accessory_Desc_20029 = {
