  UI_Accessory_Desc_31001 = {
    ContentEN = "Changes your Victory Posture.",
    ContentFR = "Permet de modifier l’animation de victoire.",
    ContentJP = "勝利ポーズを変更できます。",
    ContentKR = "클리어 동작을 변경할 수 있다.",
