  UI_Accessory_Desc_40013 = {
    ContentEN = "Activate. Engage. Advance.",
    ContentFR = "Activation. Fonctionnement. Propulsion.",
    ContentJP = "起動、運転、前進。",
    ContentKR = "활성화, 기동, 전진.",
    ContentTC = "激活，運轉，推進。",
    TextMapContent = "激活，运转，推进。",
    TextMapId = "UI_Accessory_Desc_40013"
  },
  UI_Accessory_Desc_40014 = {
    ContentEN = "O wings, soft as a fledgling's, carry my longing and fly towards the horizon where the light awaits.",
    ContentFR = "Ô ailes douces comme celles d’un oisillon, emportez mon désir et volez vers l’horizon où brille la lumière.",
    ContentJP = "雛の羽のように、そっと柔らかな翼よ。この想いを背に、あの光さす空の彼方まで、どうか──",
    ContentKR = "아기 새처럼 여린 날개여, 나의 소망을 싣고 빛나는 하늘을 향해 날아올라 다오.",
    ContentTC = "雛鳥般柔軟的翅膀啊，請你載著我的渴盼，飛向那光芒所在的天際。",
