  UI_Accessory_Desc_40055 = {
    ContentEN = "Between six layered wings, the guilty behold the fires of judgement, and the suffering knock upon the gates of heaven.",
    ContentFR = "Entre six ailes entrelacées, les coupables contemplent les flammes du jugement, tandis que les âmes en peine frappent aux portes du ciel.",
    ContentJP = "重なり合う六枚の翼の狭間で、罪ある者は審判の烈火を見、苦難を受けた者は天国の門を叩いた。",
    ContentKR = "여섯 개의 날개 사이로, 죄 지은 이는 타오르는 심판의 불길을 보았으며, 고난받는 이는 천공의 문을 두드렸다.",
    ContentTC = "交疊的六翼之間，負罪者看到了審判的烈火，受難者叩響了天穹的門扉。",
    TextMapContent = "交叠的六翼之间，负罪者看到了审判的烈火，受难者叩响了天穹的门扉。",
    TextMapId = "UI_Accessory_Desc_40055"
  },
  UI_Accessory_Desc_40056 = {
    ContentEN = "A dainty little sachet, soft and plump, dangling lightly at your hem.",
