  UI_AutoChess_ExtraBuffDesc_15 = {
    ContentEN = "<Title>Buff Effect:</> Grants Primander Ability – Frostbite. When hit by a ranged weapon attack, launch an ice spike toward the attacker, dealing damage to enemy targets hit and inflict Slow for a duration.",
