    ContentKR = "화려하고 우아하게, 스스로 빛나는 아름다움",
    ContentTC = "風華盡顯，雅韻自成。",
    TextMapContent = "风华尽显，雅韵自成。",
    TextMapId = "UI_Skin_Des_0011"
  },
  UI_Skin_Des_0121 = {
    ContentEN = "Why is one of the snowmen so much bigger than the others?",
    ContentFR = "Pourquoi, parmi tous ces bonshommes de neige, l’un d’eux paraît-il nettement plus imposant que les autres ?",
    ContentJP = "雪だるまがいっぱいあるのに、どうして1体だけやけに大きいんだろう？",
    ContentKR = "수많은 눈사람들 중에, 왜 하나가 유독 커 보이는 걸까?",
    ContentTC = "一地雪人中為什麼有一個看起來格外的大？",
    TextMapContent = "一地雪人中为什么有一个看起来格外的大？",
    TextMapId = "UI_Skin_Des_0121"
