  UI_Skin_Des_0122 = {
    ContentEN = "Between the bell's chime and turning pages, the years slip away.",
    ContentFR = "Entre la sonnerie et les pages qui se tournent, les années s’éclipsent en silence.",
    ContentJP = "ベルの音とページの間に、歳月はあっという間にすり抜けていく。",
    ContentKR = "세월이 종소리와 책장 사이에서 종종걸음으로 스쳐 지나간다.",
    ContentTC = "鈴聲與書頁間，歲月匆匆溜走。",
    TextMapContent = "铃声与书页间，岁月匆匆溜走。",
    TextMapId = "UI_Skin_Des_0122"
  },
  UI_Skin_Des_0131 = {
    ContentEN = "We drink deep on sleepless, velvet-blue nights, whistling as we race into the midnight chill.",
    ContentFR = "Dans des nuits sans sommeil, douces comme du velours bleu, nous buvons à pleines gorgées, sifflant en filant dans la fraîcheur du vent de minuit.",
    ContentJP = "私たちは青いベルベットのような眠らぬ夜に浴びるほど酒を飲み、口笛を吹きながら真夜中の涼風を駆け抜ける。",
    ContentKR = "잠 못 이루는 푸른 벨벳 같은 밤에 거침없이 술을 들이켜며, 우리는 휘파람과 함께 한밤의 서늘한 바람 속을 질주한다.",
    ContentTC = "我們在藍絲絨般的不眠之夜痛飲，吹著口哨疾馳於午夜的涼風中。",
    TextMapContent = "我们在蓝丝绒般的不眠之夜痛饮，吹着口哨疾驰于午夜的凉风中。",
    TextMapId = "UI_Skin_Des_0131"
  },
  UI_Skin_Des_0141 = {
    ContentEN = "Sin needs no hothouse. It blooms in silence, deep within the human heart.",
    ContentFR = "Le péché n’a nul besoin d’une serre pour éclore ; il fleurit silencieusement au plus profond du cœur humain.",
    ContentJP = "罪悪は温室で育まなくても、人の心にひそやかに咲き誇る。",
    ContentKR = "죄악은 온실의 보살핌 없이도, 인간의 마음속에 소리 없이 악의 꽃을 피워낸다.",
    ContentTC = "罪惡不需要溫室的滋養，便能在人心中悄然盛開。",
    TextMapContent = "罪恶不需要温室的滋养，便能在人心中悄然盛开。",
    TextMapId = "UI_Skin_Des_0141"
  },
  UI_Skin_Des_0151 = {
    ContentEN = "Drift in the midsummer breeze, and raise a glass to azure waves, to golden fireworks, and to the freedom of this moment.",
    ContentFR = "Se laisser porter par la brise estivale, lever un toast aux vagues azurées, aux feux d’artifice orangés et à l’instant de liberté que nous partageons.",
    ContentJP = "夏の潮風に身を委ね、蒼き波しぶきに、橙色の花火に、そして、この瞬間を自由に楽しむ私たちに乾杯。",
    ContentKR = "한여름의 바다 바람을 맞으며 건배하자. 새파란 물보라, 주황빛 불꽃, 그리고 자유로운 이 순간의 우리를 위하여.",
    ContentTC = "徜徉在盛夏的海風中，為蔚藍的浪花乾杯，為橙黃的焰火乾杯，為此刻無拘無束的你我乾杯",
    TextMapContent = "徜徉在盛夏的海风中，为蔚蓝的浪花干杯，为橙黄的焰火干杯，为此刻无拘无束的你我干杯。",
    TextMapId = "UI_Skin_Des_0151"
  },
  UI_Skin_Des_0161 = {
    ContentEN = "Peace in our precinct.",
    ContentFR = "Préserver la paix.",
    ContentJP = "平和を守る！",
    ContentKR = "도시의 평화를 지킨다.",
    ContentTC = "守護安寧。",
    TextMapContent = "守护安宁。",
    TextMapId = "UI_Skin_Des_0161"
  },
  UI_Skin_Des_1101 = {
    ContentEN = "Black is the colour of night — a calm, watchful veil drawn over the world. Black is the colour of shadow — a cloak that lets one remain ever near to those they hold dear. Berenica favours it.",
    ContentFR = "Le noir est la couleur de la nuit : un voile paisible posé sur le monde. Le noir est la couleur de l’ombre : une présence fidèle près de ceux que l’on aime. C’est pour cela que Berenica l’affectionne tant.",
    ContentJP = "黒は夜の色。大地を包み、安らぎと静けさをもたらす。黒は影の色。寄り添い、最も大切な人を守り続ける。ベレニカは、この色を好んでいる。",
    ContentKR = "검은색은 밤의 색으로, 대지에 고요하면서도 평온한 베일을 씌워준다. 검은색은 그림자의 색으로, 가장 가까운 사람의 곁을 떠나지 않고 지켜준다. 그래서 베레니카는 검은색을 좋아한다.",
    ContentTC = "黑色是夜晚的顏色，它為大地罩起寧靜而安心的面紗；黑色是影子的顏色，它能形影不離地守在至親之人的身旁。貝蕾妮卡喜歡這個顏色。",
    TextMapContent = "黑色是夜晚的颜色，它为大地罩起宁静而安心的面纱；黑色是影子的颜色，它能形影不离地守在至亲之人的身旁。贝蕾妮卡喜欢这个颜色。",
    TextMapId = "UI_Skin_Des_1101"
  },
  UI_Skin_Des_110101 = {
    ContentEN = "The dancer spins unceasingly, and the ball never fades.",
    ContentFR = "La danseuse tourne sans fin, et le bal ne s’achève jamais.",
    ContentJP = "踊り手は回り続け、舞踏会は決して終わらない。",
    ContentKR = "댄서는 끊없이 춤추고, 무도회는 영원히 막을 내리지 않는다.",
    ContentTC = "舞者不斷旋轉，舞會永不落幕。",
    TextMapContent = "舞者不断旋转，舞会永不落幕。",
    TextMapId = "UI_Skin_Des_110101"
  },
  UI_Skin_Des_1102 = {
    ContentEN = "Wherever she goes, the shadow of Hyperborea hangs over her — a dark, invisible cage that never lifts.",
    ContentFR = "Où qu’elle aille, l’immense ombre d’Hyperborea semble toujours peser sur elle, se changeant en une prison obscure et invisible.",
    ContentJP = "彼女の足跡のどこにでも、ヒュペリアの巨大な影が付き従う。それは永遠に晴れぬ暗雲のごとく、見えざる牢獄として彼女を静かに囲い込む。",
    ContentKR = "그녀가 어디를 가든, 휘페르보레아의 거대한 그림자가 드리워져, 마치 보이지 않는 어둠의 감옥처럼 그녀를 짓누른다.",
    ContentTC = "無論她走到何處，海伯利亞那巨大的陰影彷彿都投射在她的身上，化作無形的漆黑囚籠。",
    TextMapContent = "无论她走到何处，海伯利亚那巨大的阴影仿佛都投射在她的身上，化作无形的漆黑囚笼。",
    TextMapId = "UI_Skin_Des_1102"
  },
  UI_Skin_Des_110201 = {
    ContentEN = "The noble angel takes up the sword of judgement. Sinners shall be condemned. The innocent shall be absolved.",
    ContentFR = "L’ange immaculé brandit l’épée du jugement. Les coupables seront condamnés ; les innocents recevront l’absolution.",
    ContentJP = "高潔なる天使は裁きの剣を掲げ、罪ある者には審判を、罪なき者には赦しを与える。",
    ContentKR = "고결한 천사가 심판의 검을 쥐니, 죄 있는 자는 심판받고, 죄 없는 자는 용서를 받으리라.",
    ContentTC = "高潔的天使執起裁決的劍，她必將那有罪者審判，她必將那無罪者寬恕。",
