  UI_Skin_Des_3301 = {
    ContentEN = "A multipurpose helmet forged from a pot — sturdy armour for a scavenger girl.",
    ContentFR = "Un casque polyvalent forgé à partir d’une simple marmite — l’armure robuste d’une jeune récupératrice.",
    ContentJP = "鍋から作られた多機能ヘルメットは、ゴミ拾いの少女の堅牢な甲冑だ。",
    ContentKR = "냄비로 만든 다용도 헬멧. 넝마주이 소녀의 단단한 갑옷이다.",
