  },
  UI_Skin_Des_410101 = {
    ContentEN = "Shadows adrift beneath the moonlight; the restless whispering among the pages.",
    ContentFR = "Sous la lune, une ombre profonde ; un signet murmure d’esprits et de divinités.",
    ContentJP = "影はひとたまり、月夜に降り注ぎ、半巻のしおりにて鬼神を語る。",
    ContentKR = "달 그림자가 연못에 비치고, 낡은 책 속에선 한가로이 귀신 이야기를 전하네.",
    ContentTC = "一汪幽影灑月夜，半卷書籤話鬼神。",
    TextMapContent = "一汪幽影洒月夜，半卷书签话鬼神。",
