  UI_WeaponAccessory_Desc_10013 = {
    ContentEN = "Wings forsaken by the gods.",
    ContentFR = "Une aile reniée par les dieux.",
    ContentJP = "神にさえ背かれた羽。",
    ContentKR = "신에게 버려진 날개.",
    ContentTC = "被神遺棄的羽翼。",
