  voice_ch_char_Aote_vo_skill02_r03 = {
    ContentEN = "Cherish your last glimpse of the world.",
    ContentFR = "Admirez ce monde une dernière fois.",
    ContentJP = "最後の光景を、しっかり目に焼き付けるんだな。",
    ContentKR = "마지막 유언을 남기도록.",
    ContentTC = "最後，再看一眼這個世界吧。",
