    TextMapId = "voice_ch_char_Baiheng_vo_die_r02"
  },
  voice_ch_char_Baiheng_vo_fail = {
    ContentEN = "Fear not — here, take this to ease your pain.",
    ContentFR = "Prends ceci pour soulager la douleur... ne perds pas courage.",
    ContentJP = "慌てずに、まずはこの鎮痛剤をお飲みください。",
    ContentKR = "당황하지 말고 먼저 이 진통제를 마셔요.",
    ContentTC = "不要慌，先喝了這劑止痛藥。",
    TextMapContent = "不要慌，先喝了这剂止痛药。",
    TextMapId = "voice_ch_char_Baiheng_vo_fail"
  },
  voice_ch_char_Baiheng_vo_gain_1 = {
    ContentEN = "The road ahead is long and fraught with uncertainty... Yet, as providence has intertwined our paths, let us journey side by side, if only for a while.",
    ContentFR = "La route est longue et pleine d’incertitudes... Puisque nos chemins se croisent par le destin, accompagnons-nous un temps, le temps du voyage.",
    ContentJP = "行く末も定まらぬ旅路で……こうして巡り合えたのも、何かのご縁でしょう。しばしの間、お伴してもいいですか？",
    ContentKR = "갈 길은 먼데 미래는 불확실하기만 하네요... 이렇게 마주쳤으니, 잠시 함께 동행하죠.",
    ContentTC = "旅途漫漫，前程未定……你我既萍水相逢，便暫且相伴而行吧。",
    TextMapContent = "旅途漫漫，前程未定……你我既萍水相逢，便暂且相伴而行吧。",
    TextMapId = "voice_ch_char_Baiheng_vo_gain_1"
  },
  voice_ch_char_Baiheng_vo_gain_2 = {
    ContentEN = "I am Fushu, a healer from Huaxu. If you are injured or unwell, please, do not conceal it from me. Though my skills may have their limits, I will do everything in my power to safeguard your well-being.",
    ContentFR = "Je suis Fushu, guérisseuse de Huaxu. Si tu es blessé ou malade, ne me cache rien. Mes compétences sont limitées, mais je ferai tout pour te protéger.",
    ContentJP = "フーシュと申します。一介の医師として、華胥に身を置いております。怪我や病気の際には、どうか隠さずにおっしゃってください。未熟なりに、全力であなたをお守りします。",
    ContentKR = "부소예요. 화서의 의사라고 해두죠. 당신이 다치거나 병에 걸렸다면, 부디 저에게 숨기지 말아주세요. 의술은 아직 서툴러도, 최선을 다해서 당신을 지켜줄게요.",
    ContentTC = "扶疏，姑且算是華胥的一名醫師。你若受傷或是患病，不可向我隱瞞，雖然醫術不精，但我必定傾盡全力，保你無虞。",
    TextMapContent = "华胥药师，扶疏。虽说仍在见习，但大可放心将伤口托付于我，就算我学问不精，也总有治愈的办法。",
    TextMapId = "voice_ch_char_Baiheng_vo_gain_2"
  },
  voice_ch_char_Baiheng_vo_idle = {
    ContentEN = "Sweeping up and venting in the morning, spraying strong liquor in the afternoon, and lighting incense sticks at dusk to drive away insects — that's the only way to keep a room clean.",
    ContentFR = "Aérer le matin après avoir nettoyé, vaporiser de l’alcool fort à midi, brûler de l’encens au crépuscule, il n’y a pas mieux pour assainir une pièce.",
    ContentJP = "朝はお掃除をしたあとで換気を済ませ、昼に強いお酒で消毒をし、夕方には香を焚いて蚊を払う――こうして初めて、室内を清潔に保ち、病を遠ざけることができるのです。",
    ContentKR = "아침 청소 후 환기시키고, 오후에는 여기저기 독한 술로 소독한 다음, 저녁에는 향을 피워 모기를 쫓아야 해요. 그래야 실내를 깨끗하게 유지하고 병에 걸릴 가능성을 줄일 수 있어요.",
    ContentTC = "嗯……晨間打掃後通風，午後四處噴灑烈酒，薄暮時再點幾支香驅散蚊蟲，只有這樣才能保持室內潔淨。",
    TextMapContent = "嗯......晨间打扫后通风，午后四处喷洒烈酒，薄暮时再点几支香驱散蚊虫，只有这样才能保持室内洁净。",
    TextMapId = "voice_ch_char_Baiheng_vo_idle"
  },
  voice_ch_char_Baiheng_vo_lvup = {
    ContentEN = "Maintaining a healthful regimen and regular exercise is a fundamental duty for every healer.",
    ContentFR = "Une hygiène de vie rigoureuse est un devoir pour tout guérisseur.",
    ContentJP = "規則正しい生活習慣と適度な鍛錬――これもまた、医師の務めにございます。",
    ContentKR = "건강한 생활 습관을 유지하고 정기적으로 운동하는 것 또한 의사로서 해야 할 의무예요.",
    ContentTC = "健康作息，定時鍛煉，也是醫者應盡的義務。",
    TextMapContent = "健康作息，定时锻炼，也是医者应尽的义务。",
    TextMapId = "voice_ch_char_Baiheng_vo_lvup"
  },
  voice_ch_char_Baiheng_vo_revive = {
    ContentEN = "Like blossoms, I bloom anew.",
    ContentFR = "Comme les fleurs, je m’épanouis à nouveau.",
    ContentJP = "再び花開く時節がきました。",
    ContentKR = "꽃은 다시 필 때가 있죠.",
    ContentTC = "花有重開時。",
    TextMapContent = "花有重开时。",
