    TextMapContent = "除寒！",
    TextMapId = "voice_ch_char_Baiheng_vo_skill01_r02"
  },
  voice_ch_char_Baiheng_vo_skill02_r01 = {
    ContentEN = "In silence, all is renewed.",
    ContentFR = "Dans le silence, tout renaît.",
    ContentJP = "静寂の風に潤いを！",
    ContentKR = "고요한 봄비처럼!",
    ContentTC = "潤物無聲！",
    TextMapContent = "润物无声！",
    TextMapId = "voice_ch_char_Baiheng_vo_skill02_r01"
  },
  voice_ch_char_Baiheng_vo_skill02_r02 = {
    ContentEN = "Like the moon waxing to its fullness.",
    ContentFR = "Telle la lune éternelle.",
    ContentJP = "月が満ちるかの如く！",
    ContentKR = "달처럼 영원하게!",
    ContentTC = "如月之恒！",
