  voice_ch_char_Eve_vo_idle = {
    ContentEN = "It's too quiet in here! Don't worry — I'll make a ton of Cinders and loads of Snows! That should liven things right up~ Yeewee~",
    ContentFR = "Ce n’est pas encore assez animé ici ! Regarde, je vais copier cent Cinder, cent Snow, et remplir tous les recoins. Yiou yiou~",
    ContentJP = "ここ、まだちょっと寂しいねぇ。よーし、見てて見てて。すみっちをいっぱい、スノウっちもいっぱい複製して、すみっこまでぎゅうぎゅうに……ひぅっ♪ひぅっ♪",
    ContentKR = "여긴 너무 조용하잖아! 까망이 백 마리랑 스노우 백 명을 복제해서 여길 가득 채워 버려야겠어~ 이휴~",
    ContentTC = "這個地方還不夠熱鬧呀！看我複製一百個烏烏，一百個小白，把每一個角落都塞滿，咿嗚咿嗚~",
    TextMapContent = "这个地方还不够热闹呀！看我复制一百个乌乌，一百个小白，把每一个角落都塞满，咿呜咿呜~",
    TextMapId = "voice_ch_char_Eve_vo_idle"
  },
  voice_ch_char_Eve_vo_lvup = {
    ContentEN = "Am I stronger now? Hehe. I can't wait to show them what I can do next time!",
