  voice_ch_char_Eve_vo_victory = {
    ContentEN = "Hehe. Told you I was the strongest soldier in all of Arcano!",
    ContentFR = "Héhé, je l’avais bien dit ! Je suis le meilleur soldat de tout le Paradis !",
    ContentJP = "えへへ、言ったでしょ。わたしこそ、ワンダーランド一の兵だっ！！",
    ContentKR = "후후, 말했잖아. 난 낙원에서 제일 잘 싸우는 병사라니까!",
    ContentTC = "嘿嘿，我早都說了，我是全樂園最能打的士兵！",
    TextMapContent = "嘿嘿，我早都说了，我是全乐园最能打的士兵！",
