  voice_ch_char_Fuluo_vo_fail = {
    ContentEN = "This humiliation shall not be forgotten.",
    ContentFR = "Je graverai en moi l’humiliation de ce jour.",
    ContentJP = "今日の屈辱、決して忘れぬよう心に刻みつけます。",
    ContentKR = "오늘의 치욕은 기억해 두죠.",
    ContentTC = "我會銘記今日的恥辱。",
    TextMapContent = "我会铭记今日的耻辱。",
    TextMapId = "voice_ch_char_Fuluo_vo_fail"
  },
  voice_ch_char_Fuluo_vo_gain_01 = {
    ContentEN = "I'm Flora. It seems we share much in common: unspoken secrets, and a heart drifting without anchor. I trust we now understand each other well enough.",
    ContentFR = "Je suis Flora. Comme toi, je porte un secret obscur qu’aucun mot ne saurait dire. Comme toi, je suis une âme errante. Je me réjouis de voir qu’à présent, nous nous comprenons pleinement.",
    ContentJP = "フローラと申します。わたくしはあなたと同じように、誰にも言えない秘密を抱えている流浪の民です。こうしてお互いに分かり合えたこと、実に喜ばしいことですわ。",
    ContentKR = "플로라입니다. 당신과 마찬가지로, 말할 수 없는 어둠의 비밀을 지니고 떠도는 사람이죠. 반가워요, 이제 서로에 대해 충분히 알게 되었네요.",
    ContentTC = "芙羅拉，與您一樣，懷著無可言說的幽暗秘密，與您一樣，是個漂泊之人。很高興，我們現在已經充分了解了彼此。",
    TextMapContent = "芙罗拉，与您一样，怀着无可言说的幽暗秘密，与您一样，是个漂泊之人。很高兴，我们现在已经充分了解了彼此。",
    TextMapId = "voice_ch_char_Fuluo_vo_gain_01"
  },
  voice_ch_char_Fuluo_vo_gain_02 = {
    ContentEN = "You have returned... you kept faith with our vow. ",
    ContentFR = "Te voilà revenu... Tu as donc honoré le pacte qui nous lie.",
    ContentJP = "お戻りになったのですね……わたくしたちの誓約を、きちんとお守りになった、ということですよね。",
    ContentKR = "돌아오셨나요... 우리 계약을 지키셨네요.",
    ContentTC = "你回來了……你遵守了我們的誓約呢。",
    TextMapContent = "你回来了……你遵守了我们的誓约呢。",
    TextMapId = "voice_ch_char_Fuluo_vo_gain_02"
  },
  voice_ch_char_Fuluo_vo_idle = {
    ContentEN = "\"The evening bell urges daylight toward the horizon. Weary travellers, led by the evening star, make their way home. Now, this world belongs to the night, and to me.\"",
    ContentFR = "« La cloche du soir presse le jour vers l’horizon. Les voyageurs las, guidés par l’étoile du crépuscule, reprennent le chemin du retour. À présent, ce monde appartient... à la nuit, et à moi. »",
    ContentJP = "「夕暮れを告げる鐘は昼を地平線へと促し、疲れ切った旅人は星月夜に向けて家路を歩く。今、このうつし世は、我と深い夜と共にある」",
    ContentKR = "\"저녁 종소리가 한낮을 지평선으로 부르니, 지친 여행자는 희미한 별빛 아래 돌아가고, 이제 이 세상은 밤과 나의 것이네.\"",
    ContentTC = "「晚鐘催促白晝駛向地平，疲累的旅人們迎著昏星踏上歸途。現在這世界屬於，黑夜與我。」",
    TextMapContent = "“晚钟催促白昼驶向地平，疲累的旅人们迎着昏星踏上归途。现在这世界属于，黑夜与我。”",
    TextMapId = "voice_ch_char_Fuluo_vo_idle"
  },
  voice_ch_char_Fuluo_vo_lvup = {
    ContentEN = "It is the necessary path.",
    ContentFR = "Une épreuve nécessaire.",
    ContentJP = "これは必要な試練ですの。",
    ContentKR = "꼭 필요한 수련이었어요.",
    ContentTC = "必要的磨礪。",
    TextMapContent = "必要的磨砺。",
    TextMapId = "voice_ch_char_Fuluo_vo_lvup"
  },
  voice_ch_char_Fuluo_vo_revive = {
    ContentEN = "I shall not fall until they pay the price.",
    ContentFR = "Tant qu’ils n’auront pas payé, je dois vivre.",
    ContentJP = "彼らに断罪を下すまで、わたくしは生きねばならないのです……！",
    ContentKR = "그들이 대가를 치르기 전에 전 죽을 수 없어요.",
    ContentTC = "在他們付出代價之前，我必須活著。",
    TextMapContent = "在他们付出代价之前，我必须活着。",
    TextMapId = "voice_ch_char_Fuluo_vo_revive"
  },
  voice_ch_char_Fuluo_vo_skill01_r01 = {
    ContentEN = "The dusk has arrived.",
    ContentFR = "Le crépuscule est venu.",
    ContentJP = "来たれ、黄昏よ。",
    ContentKR = "노을이 지네요.",
    ContentTC = "黃昏已至。",
    TextMapContent = "黄昏已至。",
    TextMapId = "voice_ch_char_Fuluo_vo_skill01_r01"
  },
  voice_ch_char_Fuluo_vo_skill01_r02 = {
    ContentEN = "I shall hesitate no longer.",
    ContentFR = "Je n’hésiterai plus.",
    ContentJP = "もう迷いはしません。",
    ContentKR = "더 이상 망설이지 않겠어요.",
    ContentTC = "我已不再猶疑。",
    TextMapContent = "我已不再犹疑。",
    TextMapId = "voice_ch_char_Fuluo_vo_skill01_r02"
  },
  voice_ch_char_Fuluo_vo_skill02_r01 = {
    ContentEN = "For the future I have yet to behold.",
    ContentFR = "Pour l’avenir que je n’ai jamais contemplé.",
    ContentJP = "まだ見ぬ未来のために！",
    ContentKR = "본 적 없는 미래를 위해.",
    ContentTC = "為了我不曾見過的未來。",
    TextMapContent = "为了我不曾见过的未来。",
    TextMapId = "voice_ch_char_Fuluo_vo_skill02_r01"
  },
  voice_ch_char_Fuluo_vo_skill02_r02 = {
    ContentEN = "For the grief that was never spoken.",
    ContentFR = "Pour la tristesse scellée des disparus.",
    ContentJP = "逝く者の、黙殺される悲しみのために。",
    ContentKR = "죽은 자의 묻힌 슬픔을 위해.",
    ContentTC = "為了逝者被封緘的悲哀。",
    TextMapContent = "为了逝者被封缄的悲哀。",
    TextMapId = "voice_ch_char_Fuluo_vo_skill02_r02"
  },
  voice_ch_char_Fuluo_vo_skill02_r03 = {
    ContentEN = "Let my wrath be the last thing you feel.",
    ContentFR = "Je forge ici toute ma colère... et tu en paieras le prix.",
    ContentJP = "我が怒りの全てはここに刻まれ、汝の命は捧げられる。",
    ContentKR = "나의 분노를 여기에 녹여, 그대의 생명을 제물로 삼겠다.",
    ContentTC = "我將憤怒盡數熔鑄於此，而你必將償付代價。",
    TextMapContent = "我将愤怒尽数熔铸于此，而你必将偿付代价。",
    TextMapId = "voice_ch_char_Fuluo_vo_skill02_r03"
  },
  voice_ch_char_Fuluo_vo_topic_01_1 = {
    ContentEN = "Most do. Since childhood, the spine is trained to hold itself straight, yet never rigid, like a string; and a skirt must learn to turn slowly, like petals slowly coming into bloom.",
    ContentFR = "Pour la plupart, oui. Dès l’enfance, on leur enseigne à garder le dos droit comme la corde d’un luth : tendue, sans jamais être raide. Lorsqu’elles se retournent, le mouvement doit être lent, et les plis de leur robe s’ouvrir comme des pétales en fleur.",
    ContentJP = "ほとんどの者はそうですわ。幼き頃から教え込まれるのです。座るときは背筋を弦のごとく張りつつも堅くならず、振り返るときはゆっくりと、スカートは花びらのように優雅に広がるべきだと。",
    ContentKR = "대부분은 그래요. 어릴 때부터 그렇게 교육받거든요. 앉을 때는 등을 하프의 현처럼 곧게 펴면서도, 너무 뻣뻣해선 안 돼요. 돌아설 때는 치맛자락이 활짝 핀 꽃처럼 펼쳐지도록 천천히 몸을 돌려야 하죠.",
    ContentTC = "大多數人是這樣。她們從幼時便被教導，坐下時脊背要像琴弦那樣繃直卻不僵硬；轉身要慢，裙襬要像舒展的花瓣一樣緩緩散開。",
    TextMapContent = "大多数人是这样。她们从幼时便被教导，坐下时脊背要像琴弦那样绷直却不僵硬；转身要慢，裙摆要像舒展的花瓣一样缓缓散开。",
    TextMapId = "voice_ch_char_Fuluo_vo_topic_01_1"
  },
  voice_ch_char_Fuluo_vo_topic_01_2 = {
    ContentEN = "Joy and sorrow alike must be worn with restraint. One must neither grow indifferent nor lose composure. A smile, a tear — even the faintest curve of the lips — should carry the weight of measured grace.",
    ContentFR = "La joie comme la peine doivent elles aussi être soigneusement mesurées. Il ne faut être ni froide, ni trop démonstrative. Le sourire comme les larmes, jusqu’à la courbe des lèvres, doivent posséder la juste élégance du balancement d’une boucle d’oreille : sobre, gracieux, irréprochable.",
    ContentJP = "喜びも、悲しみもすべて慎重に。冷淡であってはならず、しかし感情をあまりに露わにするのも無作法ですわ。微笑むときも、涙をこぼすときも、口元の弧の動きはイヤリングの揺れ幅のよう、品よく、雅やかに。",
    ContentKR = "기쁨이나 슬픔을 드러낼 때도 조심해야 해요. 너무 차가워선 안 되지만, 감정을 지나치게 드러내는 것도 실례예요. 미소 지을 때나 눈물을 흘릴 때, 입술 끝의 움직임은 귀걸이가 흔들리는 정도로만 허용돼요. 신분에 맞게, 품위를 지키면서, 예의 바르게 감정을 드러내야 하죠.",
    ContentTC = "喜悅和悲傷也要細細度量。你不可以冷漠，但過於外露的情緒也是失禮的。微笑和哭泣時嘴角的弧度要像耳環晃動的幅度一樣，得體，雅觀，恰如其分。",
    TextMapContent = "喜悦和悲伤也要细细度量。你不可以冷漠，但过于外露的情绪也是失礼的。微笑和哭泣时嘴角的弧度要像耳环晃动的幅度一样，得体，雅观，恰如其分。",
    TextMapId = "voice_ch_char_Fuluo_vo_topic_01_2"
  },
  voice_ch_char_Fuluo_vo_topic_01_3 = {
    ContentEN = "Heh... Every noblewoman has, at some point, lamented such tedious formalities to her maid. Only to be reminded that society is her battlefield — and the smallest lapse may stain her family's name.",
    ContentFR = "Ah... Chaque jeune noble s’est un jour plainte de ces rites interminables auprès de sa servante. Et chaque servante lui rappelait ceci : la société est son champ de bataille, et la moindre faute peut couvrir sa maison de honte.",
    ContentJP = "ふふ、レディーたちは、一度や二度、この煩わしい礼節にメイドたちへ愚痴をこぼしたことがあるでしょう。するとメイドたちはこう告げるのです、社交こそがあなた様の戦場であり、些細な失礼も家の名に恥をかかせることになる、と。",
    ContentKR = "후후, 귀족 소녀라면 누구나 메이드에게 이런 복잡한 예절에 대해 불평할걸요? 하지만 메이드는 아랑곳하지 않고 충고하겠죠. 사교란 보이지 않는 전쟁터고, 단 한 번의 사소한 실수로도 가문의 명예에 먹칠을 할 수 있다고요.",
    ContentTC = "呵呵，每一個貴族姑娘都曾向她們的女僕抱怨過這些繁冗的禮節。然後她們的女僕便會告訴她們，社交就是她的戰場，任何一次小小的失禮都會令家族蒙羞。",
    TextMapContent = "呵呵，每一个贵族姑娘都曾向她们的女仆抱怨过这些繁冗的礼节。然后她们的女仆便会告诉她们，社交就是她的战场，任何一次小小的失礼都会令家族蒙羞。",
    TextMapId = "voice_ch_char_Fuluo_vo_topic_01_3"
  },
  voice_ch_char_Fuluo_vo_topic_01_4 = {
    ContentEN = "For the nobility, such courtesies are but the form of dignity. The newly wealthy, however, cling to the form desperately, hoping imitation alone might grant them nobility.",
    ContentFR = "Les nobles s’en servent pour afficher une dignité de façade. Les nouveaux riches, eux, s’y adonnent avec ferveur, espérant qu’en imitant la forme, ils acquerront la substance.",
    ContentJP = "貴族たちは、形ばかりの礼節で体面を誇示し、成金の富豪たちはそれを熱狂に学び、貴族のように見せかけるのですわ。",
    ContentKR = "귀족들은 이런 겉치레뿐인 예절로 스스로를 과시하고, 신흥 부자들은 어떻게든 귀족과 비슷해 보이기 위해, 열광적으로 따라해요.",
    ContentTC = "貴族們靠這些徒有其表的禮儀彰顯體面，新發家的富人則狂熱地學習這些，讓自己看上去像極了貴族。",
    TextMapContent = "贵族们靠这些徒有其表的礼仪彰显体面，新发家的富人则狂热地学习这些，让自己看上去像极了贵族。",
    TextMapId = "voice_ch_char_Fuluo_vo_topic_01_4"
  },
  voice_ch_char_Fuluo_vo_topic_01_5 = {
    ContentEN = "It is not courtesy they value, but distinction — the careful line that sets them apart from the common folk. If one day, the emperor were to take delight in the sounds of the sty, then all the people in Dismania shall praise such sounds as the most beautiful.",
    ContentFR = "Ce qu’ils chérissent n’est pas l’étiquette, mais la frontière qu’elle trace entre eux et les gens du peuple. Si un jour Sa Majesté impériale se passionnait pour le grognement des porcelets, toute Dismania proclamerait aussitôt qu’il s’agit là du plus noble des chants.",
    ContentJP = "彼らが気にするのは礼節そのものではなく、いかにして自分をいわゆる「田舎者」と区別することですわ。たとえ、陛下が小豚の鳴き声の真似に夢中になったとしても、全ディズマニアの人々は、豚の鳴き声こそが最も響きのいい声だと称賛することになるのでしょう。",
    ContentKR = "사실 그들이 진짜 원하는 건 예의가 아니라, 자신을 '촌뜨기'들과 구별 짓는 거예요. 만약에 황제 폐하께서 돼지 울음 소리를 흉내 내는 일에 푹 빠지신다면, 온 디즈마니아 사람들은 말할 거예요. 돼지 울음 소리가 세상에서 제일 아름답다고 말이죠.",
    ContentTC = "他們在意的從不是禮儀本身，而是如何把自己和「泥腿子」區分開。如果有一天皇帝陛下熱衷於學習小豬叫，那麼全迪斯瑪尼亞人都會說豬叫是最優美的聲音。",
    TextMapContent = "他们在意的从不是礼仪本身，而是如何把自己和“泥腿子”区分开。如果有一天皇帝陛下热衷于学习小猪叫，那么全迪斯玛尼亚人都会说猪叫是最优美的声音。",
    TextMapId = "voice_ch_char_Fuluo_vo_topic_01_5"
  },
  voice_ch_char_Fuluo_vo_topic_02_1 = {
    ContentEN = "Dismania... The city encased in irony walls, the precious Phoxene yet the decaying root of Hyperborea... my so-called homeland.",
    ContentFR = "Dismania... cette cité enfermée derrière un immense rempart d’acier. Joyau étincelant de Phoxène d’Hyperborea... et racine gangrenée du même empire. Ma... « patrie ».",
    ContentJP = "ディズマニア……あの鋼鉄の盾に包まれた都市、ヒュペリアの煌めく月ノ石、ヒュペリアを腐敗した源、そしてわたくしの「故郷」。",
    ContentKR = "디즈마니아... 그 거대한 강철 방패로 둘러싸인 도시, 휘페르보레아의 찬란한 월석이자 썩어 문드러진 뿌리인... 제 '고향' 말이군요.",
    ContentTC = "迪斯瑪尼亞啊……那座包裹在鋼鐵巨盾中的城市，海伯利亞璀璨的月石，也是海伯利亞腐壞的根須……我的「故鄉」。",
    TextMapContent = "迪斯玛尼亚啊……那座包裹在钢铁巨盾中的城市，海伯利亚璀璨的月石，也是海伯利亚腐坏的根须……我的“故乡”。",
    TextMapId = "voice_ch_char_Fuluo_vo_topic_02_1"
  },
  voice_ch_char_Fuluo_vo_topic_02_2 = {
    ContentEN = "Many long for their hometowns. As for me... it was merely a place I spent years trying to escape.",
    ContentFR = "Je sais que beaucoup languissent de leur terre natale. Pour moi... ce fut surtout un lieu qu’il m’a fallu des années à fuir.",
    ContentJP = "多くの者は故郷を懐かしむでしょう。しかし、わたくしにとって、それは長い歳月をかけてやっと逃げ出した場所に過ぎませんわ。",
    ContentKR = "많은 사람들이 고향을 그리워한다는 거 알아요. 하지만 저에게 그곳은, 오랜 시간을 들여 간신히 탈출한 곳이었어요.",
    ContentTC = "我知道很多人思念他們的故鄉。但對我來說，那卻是一個花了很長時間逃離的地方。",
    TextMapContent = "我知道很多人思念他们的故乡。但对我来说，那却是一个花了很长时间逃离的地方。",
    TextMapId = "voice_ch_char_Fuluo_vo_topic_02_2"
  },
  voice_ch_char_Fuluo_vo_topic_02_3 = {
    ContentEN = "But I know the day will come when I walk those streets again. Not as the exile, but as the one who returns in triumph.",
    ContentFR = "Mais je sais aussi qu’un jour j’y retournerai. Et ce jour-là, je n’errerai plus en exilée... j’y entrerai en victorieuse, portée par la vengeance.",
    ContentJP = "それでも、わたくしはいつか必ず戻る日が来ると信じておりますわ。その時、もはや流浪の民ではなく、復讐者として凱旋するでしょう。",
    ContentKR = "알아요, 전 언젠가 돌아가게 될 거예요. 하지만 그날이 오면, 전 떠도는 망명자 신세가 아니라, 당당한 복수자의 모습으로 돌아갈 거예요.",
    ContentTC = "但我也知道，我總有一天會回去的。而那時，我不會再以流亡者的身份流離，而是以復仇者的姿態凱旋。",
    TextMapContent = "但我也知道，我总有一天会回去的。而那时，我不会再以流亡者的身份流离，而是以复仇者的姿态凯旋。",
    TextMapId = "voice_ch_char_Fuluo_vo_topic_02_3"
  },
  voice_ch_char_Fuluo_vo_topic_03_1 = {
    ContentEN = "Indeed. My mother chose it. She wished: \"Let the blossoms of spring remain unending, and the golden hours stay forever warm.\" A beautiful wish... one I have failed to fulfill.",
    ContentFR = "Oui. C’est ma mère qui me l’a donné. « Puisse la floraison du printemps ne jamais se faner, comme les heures couleur de miel ne sauraient pâlir. » Elle m’a donné ce nom avec une telle bénédiction... et je n’ai pas su en accomplir le vœu.",
    ContentJP = "ええ、この名は母上がわたくしに付けてくれたものですわ。「春の日の花々と同じく決して散らぬ、色褪せぬように」と、そうした祝福を込めて名付けてくれたのに、わたくしはその願いを叶えることができませんでした。",
    ContentKR = "맞아요. 어머니는 '봄날의 꽃이 시들지 않는 것처럼, 꿀처럼 달콤한 시간이 영원히 사라지지 않기를' 바라며 제 이름을 지으셨어요. 하지만 전 어머니가 원하시는 것을 이룰 수 없게 되어버렸네요.",
    ContentTC = "嗯，這個名字是母親為我取的。「願春日的群花永不凋零，正如蜜色的光陰永不消褪。」她懷著這樣的祝福為我取了名字，我卻無法讓她得償所願。",
    TextMapContent = "嗯，这个名字是母亲为我取的。“愿春日的群花永不凋零，正如蜜色的光阴永不消褪。”她怀着这样的祝福为我取了名字，我却无法让她得偿所愿。",
    TextMapId = "voice_ch_char_Fuluo_vo_topic_03_1"
  },
  voice_ch_char_Fuluo_vo_topic_03_2 = {
    ContentEN = "Then your kindness brings me warmth. Thank you.",
    ContentFR = "Alors tes paroles sont pour moi un rayon de chaleur. Merci.",
    ContentJP = "お心遣いに深く感謝いたします。",
    ContentKR = "그럼 당신의 위로는 따스한 햇볕이겠네요. 고마워요.",
    ContentTC = "那你的慰藉便是一束暖陽了。謝謝你。",
    TextMapContent = "那你的慰藉便是一束暖阳了。谢谢你。",
    TextMapId = "voice_ch_char_Fuluo_vo_topic_03_2"
  },
  voice_ch_char_Fuluo_vo_topic_04_1 = {
    ContentEN = "Why ask? It is but a dreary tale, long stretches of loneliness, and little else.",
    ContentFR = "Pourquoi désires-tu le savoir ? C’est une histoire terne... où ne s’étirent que de longues pages de solitude.",
    ContentJP = "なぜこんなことを知りたいのでしょう？それは、つまらぬ話に過ぎないですわ。長々と続く孤独以外、何ひとつもありませんでしたわ。",
    ContentKR = "그게 왜 궁금한가요? 지루한 이야기일 뿐이에요. 기나긴 고독말고는 아무것도 없거든요.",
    ContentTC = "為什麼想知道這個呢？那是一段無趣的故事，除了長篇累牘的孤獨外空無一物。",
    TextMapContent = "为什么想知道这个呢？那是一段无趣的故事，除了长篇累牍的孤独外空无一物。",
    TextMapId = "voice_ch_char_Fuluo_vo_topic_04_1"
  },
  voice_ch_char_Fuluo_vo_topic_04_2 = {
    ContentEN = [[
That is true, at least by day. But... I wonder whether you can truly understand it.
To be surrounded at all hours, hands kissed, blessings murmured with reverence, and conversations of poetry, of plays, of the flowers in the garden...]],
    ContentFR = "Le jour, c’était vrai. Mais... je me demande si tu peux saisir cette sensation. Être entourée sans cesse. Voir des lèvres se poser sur ta main. Recevoir des bénédictions humbles et révérencieuses. Entendre parler poésie, théâtre... ou des fleurs du jardin.",
    ContentJP = "昼は確かにそうですわ……でも……あなたは、この感覚が分かるでしょうか。人々があなたの周りに集い、手に口づけを捧げ、敬意をもって祝福を贈り、詩や劇、庭園の花について語り合うのです。",
    ContentKR = "낮에는 그렇죠. 하지만... 당신이 이해할지 모르겠네요. 사람들은 곁에 모여, 손등에 키스해 주고, 존경과 겸손을 담아 축복을 건네고, 시와 연극, 정원에 핀 꽃에 대해 이야기하죠.",
    ContentTC = "白天的確是如此。但……我不知道你是否可以體會那種感覺：人們圍繞著你，親吻你的手背，恭敬而謙卑地和你獻上祝福，和你談論詩歌，劇目，庭園裡的花。",
    TextMapContent = "白天的确是如此。但……我不知道你是否可以体会那种感觉：人们围绕着你，亲吻你的手背，恭敬而谦卑地和你献上祝福，和你谈论诗歌，剧目，庭园里的花。",
    TextMapId = "voice_ch_char_Fuluo_vo_topic_04_2"
  },
  voice_ch_char_Fuluo_vo_topic_04_3 = {
    ContentEN = "Yet whenever I sought conversation beyond courtesy, they would lower their heads and claim they dared not overstep.",
    ContentFR = "Et pourtant, dès que je souhaitais parler de quelque chose de plus sincère, tous baissaient les yeux en disant ne pas oser franchir les limites.",
    ContentJP = "しかし、もう少し別の話を彼らと語り合いたいとするたび、彼らは慎ましく頭を垂れ、恐れ入りますと告げるのですわ。",
    ContentKR = "하지만 조금만 더 이야기하려고 하면, 그들은 곧바로 겸손하게 고개를 숙이며, 감히 선을 넘을까 두렵다고 말할 거랍니다.",
    ContentTC = "但每當你希望和他們多談一些什麼的時候，他們就會謙卑地低下頭，說自己不敢逾矩。",
    TextMapContent = "但每当你希望和他们多谈一些什么的时候，他们就会谦卑地低下头，说自己不敢逾矩。",
    TextMapId = "voice_ch_char_Fuluo_vo_topic_04_3"
  },
  voice_ch_char_Fuluo_vo_topic_04_4 = {
    ContentEN = "Later, I came to understand. As the daughter of the late Emperor, any intimacy beyond propriety might place them at risks.",
    ContentFR = "Plus tard, j’ai compris. J’étais la fille de l’empereur défunt. Toute proximité déplacée pouvait leur attirer des ennuis.",
    ContentJP = "のちにわたくしは知ったのです、わたくしが前代の皇帝の娘であるがゆえに、いかなる僭越の交わりも、彼らに予期せぬ危険をもたらすかもしれないのだと。",
    ContentKR = "나중에야 알았어요. 전대 황제의 딸과 너무 가깝게 지내는 건, 그들에게 불필요한 위험을 가져올 뿐이라는 걸요.",
    ContentTC = "後來我知道，因為我是前代皇帝的女兒，任何越界的交情都可能給他們帶來不必要的風險。",
    TextMapContent = "后来我知道，因为我是前代皇帝的女儿，任何越界的交情都可能给他们带来不必要的风险。",
    TextMapId = "voice_ch_char_Fuluo_vo_topic_04_4"
  },
  voice_ch_char_Fuluo_vo_topic_04_5 = {
    ContentEN = "At night, I would return to that high tower. Only the moon kept me company. Two solitary souls, adrift in the silence of darkness. For the most part, I simply watched it flowing slowly toward the far edge of the sky.",
    ContentFR = "Et la nuit, je retournais dans cette haute tour. Dans ma chambre, seule la lune me tenait compagnie. Elle aussi errait seule, flottant sur la mer obscure du ciel nocturne. Alors je la regardais dériver jusqu’à l’autre rive des cieux.",
    ContentJP = "そして夜が訪れると、わたくしはあの高き塔へ戻らねばなりません。寝室で、共にいてくれるのは月だけで…月もまたひとりぼっちで夜の海に身を任せて漂っている。わたくしはただ、月が天の彼方へと漂っていくのを見つめているだけですわ。",
    ContentKR = "그러다 밤이 오면, 전 그 높은 탑으로 돌아가야 했죠. 침실에서 매일 곁에 있어 주는 건 오직 달뿐이었어요. 달도 저처럼 혼자 깊은 밤바다를 표류하고 있었죠. 전 그저 그 달이 하늘 맞은편에 다다를 때까지 바라보았고요.",
    ContentTC = "而到了晚上，我就要回到那座高塔上去，在臥房裡，陪伴我的只有月亮，它也獨自一個，在幽深的夜海中漂流。我就這樣看著它漂流到天的另一岸。",
    TextMapContent = "而到了晚上，我就要回到那座高塔上去，在卧房里，陪伴我的只有月亮，它也独自一个，在幽深的夜海中漂流。我就这样看着它漂流到天的另一岸。",
    TextMapId = "voice_ch_char_Fuluo_vo_topic_04_5"
  },
  voice_ch_char_Fuluo_vo_topic_04_6 = {
    ContentEN = "I still remember that night at Icelake Station. I was gazing at the moon when you told me you would help me reclaim my freedom.",
    ContentFR = "Oui. Je me souviens encore de cette nuit-là, à la gare de Givrelac. Je contemplais la lune... et tu m’as dit que tu m’aiderais à reconquérir ma liberté.",
    ContentJP = "ええ、おっしゃった通りですわ。あの夜のアイスレイク城の駅でのことが、今も覚えておりますわ。わたくしが月を見つめていた時、あなたが、わたくしの自由を取り戻してくださると告げてくださった。",
    ContentKR = "맞아요. 아이스레이크 시티 기차역의 그날 밤이 아직도 기억나요. 전 달을 바라보고 있었고, 당신은 내가 자유를 되찾게 도와주겠다고 했죠.",
    ContentTC = "是的。我還記得在冰湖城車站的那一晚。我凝望著月亮，而你告訴我，你願意幫助我重獲自由。",
    TextMapContent = "是的。我还记得在冰湖城车站的那一晚。我凝望着月亮，而你告诉我，你愿意帮助我重获自由。",
    TextMapId = "voice_ch_char_Fuluo_vo_topic_04_6"
  },
  voice_ch_char_Fuluo_vo_topic_04_7 = {
    ContentEN = "In that moment, I knew a different future had begun, and the dark would never again feel so vast.",
    ContentFR = "À cet instant, j’ai compris que désormais... mon clair de lune ne serait plus jamais solitaire.",
    ContentJP = "その時、わたくしは気付いたのです、これから先、もう孤独ではないのだと。",
    ContentKR = "그 순간 깨달았어요. 제 달빛은, 더 이상 고독하지 않을 거란 걸요.",
    ContentTC = "那時我便明白，從今以後，我的月色再也不會如此孤獨。",
    TextMapContent = "那时我便明白，从今以后，我的月色再也不会如此孤独。",
    TextMapId = "voice_ch_char_Fuluo_vo_topic_04_7"
  },
  voice_ch_char_Fuluo_vo_topic_05_1 = {
    ContentEN = "She was sent to attend me. We share no blood. But... she felt closer to me than the Emperor ever did. In truth, Hilda was the one who felt like family.",
    ContentFR = "Elle fut envoyée pour me servir. Aucun lien de sang ne nous unit. Pourtant... plus encore que l’empereur qui siège aujourd’hui au Palais de Bellona, et dont je partage la lignée, Hilda est pour moi une véritable famille.",
    ContentJP = "彼女は、わたくしに仕えるために遣わされたメイドです、血の繋がりなど、まったくありませんわ。しかし、今ベローナ宮殿に座する、血の繋がりの皇帝よりも、ヒルダこそが、わたくしにとっての「家族」に近い存在です。",
    ContentKR = "힐다는... 제 시중을 들도록 보내진 메이드고, 아무런 혈연 관계도 없어요. 하지만 베로나 궁전에 계신 그분보단, 힐다가 오히려 제 '가족' 같아요.",
    ContentTC = "她是被派來侍奉我的女僕，我們沒有任何血緣關係。但比起如今坐在柏羅納宮的那位與我有著相似血脈的皇帝，希爾妲更像是我的「親人」。",
    TextMapContent = "她是被派来侍奉我的女仆，我们没有任何血缘关系。但比起如今坐在柏罗纳宫的那位与我有着相似血脉的皇帝，希尔妲更像是我的“亲人”。",
    TextMapId = "voice_ch_char_Fuluo_vo_topic_05_1"
  },
  voice_ch_char_Fuluo_vo_topic_05_2 = {
    ContentEN = "She was already used to overstepping the bounds. In her eyes, I am neither \"Her Highness\" nor some claimant to the throne. I am merely Flora. And I... like this overstepping.",
    ContentFR = "Elle a depuis longtemps pris l’habitude de me manquer de respect. À ses yeux, je ne suis ni « Son Altesse », ni une prétendante au trône. Je suis simplement Flora. Et moi... j’aime cette irrévérence.",
    ContentJP = "彼女は、すでにわたくしに対して僭越な態度を取ることに慣れていますわ。彼女にとって、わたくしは決して「尊き殿下」でも、「皇位を狙う者」でもなく、ただの「フローラ」に過ぎません。そして、わたくしは……そんな彼女の僭越を、好ましく思っております。",
    ContentKR = "힐다는 멋대로 선을 넘는 게 습관이죠. 힐다에게 전 '존귀한 전하'도, '황위를 넘보는 자'도 아닌, 오직 '플로라'일 뿐이에요. 근데 전... 힐다가 그렇게 선을 넘어 주는 게 좋아요.",
    ContentTC = "她早已習慣對我僭越。在她的眼裡我從來不是什麼「尊貴的殿下」，也不是什麼「皇位覬覦者」，只是「芙羅拉」。而我……喜歡她這樣的僭越。",
    TextMapContent = "她早已习惯对我僭越。在她的眼里我从来不是什么“尊贵的殿下”，也不是什么“皇位觊觎者”，只是“芙罗拉”。而我……喜欢她这样的僭越。",
    TextMapId = "voice_ch_char_Fuluo_vo_topic_05_2"
  },
  voice_ch_char_Fuluo_vo_victory = {
    ContentEN = "Father, mother... grant me the strength to see this through.",
    ContentFR = "Père... Mère... accordez-moi d’accomplir mon vœu.",
    ContentJP = "父上、母上、どうか祈っていてください。わたくしの願いが成就するように。",
    ContentKR = "아버지, 어머니, 제 소원이 이뤄질 수 있도록 절 지켜 주세요.",
    ContentTC = "父親，母親，請護佑我得償所願。",
    TextMapContent = "父亲，母亲，请护佑我得偿所愿。",
    TextMapId = "voice_ch_char_Fuluo_vo_victory"
  },
  voice_ch_char_Fuluo_vo_welcome = {
    ContentEN = "Good day. You may kiss my hand, and let this day bring us peace and safety. ",
    ContentFR = "Bonjour. Embrasse ma main... et puissions-nous traverser cette journée sains et saufs.",
    ContentJP = "ごきげんよう。さあ、わたくしの手に口づけをしてちょうだい。今日も時の巡るまま、恙なく過ごせますように……",
    ContentKR = "안녕하세요. 제 손등에 키스해 주세요. 오늘도 우리 모두 무사히 보내길 바라죠.",
    ContentTC = "日安。親吻我的手背吧，願我們都平安度過今天。",
    TextMapContent = "日安。亲吻我的手背吧，愿我们都平安度过今天。",
    TextMapId = "voice_ch_char_Fuluo_vo_welcome"
  },
  voice_ch_char_Haier_vo_appear = {
    ContentEN = "Where are the sinners?",
    ContentFR = "Où se terrent les criminels ?",
    ContentJP = "罪人たちは、どこにいる？",
    ContentKR = "죄수는? 죄수는 어디 있지?",
    ContentTC = "罪徒呢，他們在哪裡？",
    TextMapContent = "罪徒呢，他们在哪里？",
    TextMapId = "voice_ch_char_Haier_vo_appear"
  },
  voice_ch_char_Haier_vo_battleidle = {
    ContentEN = "Are you frightened? I thought you were tougher than the other sinners. How disappointing.",
    ContentFR = "Tu trembles ? Je pensais que tu valais mieux que les autres vermines. Décevant.",
    ContentJP = "臆したか？他の罪人とは違うと思ったが……失望したぞ。",
    ContentKR = "두렵다고? 넌 다른 죄수들과는 다를 줄 알았는데. 실망스럽군.",
    ContentTC = "膽怯了？還以為你和其他的囚犯不同，真令人失望。",
    TextMapContent = "胆怯了？还以为你和其他的囚犯不同，真令人失望。",
