  voice_ch_char_Haier_vo_skill02_r02 = {
    ContentEN = "No mercy!",
    ContentFR = "Pas de pitié !",
    ContentJP = "罪深いやつめ！",
    ContentKR = "죽어도 시원찮은 죄!",
    ContentTC = "罪不容誅！",
    TextMapContent = "罪不容诛！",
    TextMapId = "voice_ch_char_Haier_vo_skill02_r02"
  },
  voice_ch_char_Haier_vo_skill02_r03 = {
    ContentEN = "Count your sins!",
    ContentFR = "Énumérez vos péchés !",
    ContentJP = "お前の罪を数えるがいい！",
    ContentKR = "네 죄를 세어 봐라!",
    ContentTC = "細數你的罪惡！",
