    ContentFR = "Tu es de retour. Qu’est-ce que tu comptes faire aujourd’hui ? Te reposer à la maison, peut-être ?",
    ContentJP = "お帰りなさい。今日は何をする？それとも家で休もうか？",
    ContentKR = "돌아왔구나. 오늘은 뭐 할 거야? 집에서 쉴 거야?",
    ContentTC = "你回來了。今天打算做什麼？還是在家休息？",
    TextMapContent = "你回来了。今天打算做什么？还是在家休息？",
    TextMapId = "voice_ch_char_Heitao_vo_welcome"
  },
  voice_ch_char_Kami_vo_appear = {
    ContentEN = "Time to stock up on a few bottles for The Asphodel.",
    ContentFR = "Il est temps de remplir la cave des Asphodèles.",
    ContentJP = "ふふ、そろそろ新しいお酒を仕入れないと。",
    ContentKR = "아스포델에 새로운 술이 들어왔어.",
    ContentTC = "水仙平原又要添置些新酒了。",
    TextMapContent = "水仙平原又要添置些新酒了。",
    TextMapId = "voice_ch_char_Kami_vo_appear"
  },
  voice_ch_char_Kami_vo_battleidle = {
