  voice_ch_char_Kami_vo_skill02_r03 = {
    ContentEN = "Fire's the same colour as wine. Look at that lovely crimson...",
    ContentFR = "Le feu a la même couleur que le vin... regarde ce rouge magnifique.",
    ContentJP = "火も酒も、本当に美しい緋色だわ…",
    ContentKR = "불은 술처럼 아름다운 다크 레드...",
    ContentTC = "火與酒的顏色一樣，這漂亮的殷紅……",
    TextMapContent = "火与酒的颜色一样，这漂亮的殷红……",
    TextMapId = "voice_ch_char_Kami_vo_skill02_r03"
