    ContentFR = "Dieu de l’Amour... Ne m’abandonne pas...",
    ContentJP = "神様……私を見捨てないで……",
    ContentKR = "사랑의 신이시여... 저를 버리지 마세요...",
    ContentTC = "愛之神……不要拋棄我……",
    TextMapContent = "爱之神……不要抛弃我……",
    TextMapId = "voice_ch_char_Shuimu_vo_die_r01"
