  voice_ch_char_Shuimu_vo_die_r02 = {
    ContentEN = "Ciao, amore mio.",
    ContentFR = "Adieu... mon amour...",
    ContentJP = "チャオ……アモーレ・ミオ……",
    ContentKR = "Ciao... amoremio...",
    ContentTC = "永別了……我的愛人……",
