  voice_ch_char_Shuimu_vo_fail = {
    ContentEN = "Failure hurts... I could really use a bit of comfort from you.",
    ContentFR = "C’est trop triste... J’aurais vraiment besoin d’un peu de réconfort de ta part...",
    ContentJP = "泣きそうなの……慰めてくれないと、このままじゃ戦えないわ。",
    ContentKR = "슬퍼요... 누군가 위로해 주면 다시 싸울 수 있을 텐데.",
    ContentTC = "好難過……需要安慰一下才能繼續戰鬥哦。",
    TextMapContent = "好难过……需要安慰一下才能继续战斗哦。",
    TextMapId = "voice_ch_char_Shuimu_vo_fail"
  },
  voice_ch_char_Shuimu_vo_gain = {
    ContentEN = "What a romantic encounter! Was this the God of Love's work? I'm Rebecca, a perfumer. How about indulging in a truly unique scent, the L'essence De L'amour? I made it myself.",
    ContentFR = "Quelle rencontre romantique ! Est-ce un signe du Dieu de l’Amour ? Je suis Rebecca, la parfumeuse. Que dirais-tu d’essayer mon parfum unique, l’Essence de l’Amour ?",
    ContentJP = "まぁ、なんてロマンチックな出会い。もしかして愛の神様のお導きかしら……うふふ、私は調香師のレベッカよ。あなたは近いうちに……私の調香した特別な「愛のアロマ」を、欲しがるようになるかも。",
    ContentKR = "정말 로맨틱한 만남이네요. 사랑의 신이 인도해 주셨을까요? 후훗, 전 조향사 레베카랍니다. 제가 직접 만든, 하나뿐인... '사랑의 아로마'를 살 생각 없나요?",
    ContentTC = "真是浪漫的相遇，莫非這就是愛之神的指引？呵呵，我是調香師麗蓓卡。也許你會想買一瓶……我親手調配的、獨一無二的，「愛之香薰」。",
