  voice_ch_char_Songlu_vo_fail = {
    ContentEN = "Filbert, are you okay? Are you hurt? Oh my little sweetie, lemme give you a hug.",
    ContentFR = "Oh non, Filbert ! Tu t’es fait mal ? Allez, un gros câlin !",
    ContentJP = "ヘーゼルナッツ、大丈夫？鼻が痛いの……ほら、痛いの痛いの……飛んでけ～",
    ContentKR = "헤이즐넛 괜찮아? 코는 어때... 자, 쓰다듬으면 안 아플 거야... 쓰담쓰담...",
    ContentTC = "榛子還好嗎？鼻子痛不痛……來，摸一摸就不痛啦……摸一摸……",
