  voice_ch_char_Zhiliu_vo_skill02_r02 = {
    ContentEN = "Stratagem's storm crescendos.",
    ContentFR = "La tempête stratégique gagne en puissance.",
    ContentJP = "巽為風――その力、ますます強し。",
    ContentKR = "바람아, 번개를 불러다오!",
    ContentTC = "震起巽風，其勢愈強。",
